(function(){
'use strict';
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const Q=(id,senseId,errorType,prompt,answer,d1,d2,explain)=>({id,senseId,type:'辨义与用法',errorType,prompt,options:[answer,d1,d2],answer,explain});
const P=(w,origin,contexts,mistakes,quiz,...legacy)=>{if(Array.isArray(contexts))return D(w,{etymology:E(origin,w),contexts,mistakes,quiz});const [domain,grammar,rationale,m,qs]=legacy;return D(w,{etymology:E(origin,w),contexts:[C(w+'.s1',domain,mistakes,quiz,contexts,grammar,rationale)],mistakes:[m],quiz:qs});};
P('supercontinent','Formed from super- “above, beyond” + continent; continent comes from Latin continentem “continuous land.”',[C("supercontinent.s1","geology","Geologists reconstructed Pangaea as a supercontinent assembled from several earlier landmasses.","地質學家重建盤古大陸，認為它是一個由數個早期陸塊組成的超級大陸。","A supercontinent combines multiple continental plates into one very large landmass.","The prefix super- intensifies continent; the noun is the object of reconstructed.","The example distinguishes a joined giant landmass from an ordinary continent.")],[M("The map labels the tiny island of Malta a supercontinent.","The map labels Pangaea a supercontinent.","A supercontinent is an exceptionally large landmass assembled from smaller continental plates, not a small island.")],[Q("supercontinent.q1","supercontinent.s1","meaning","What makes a landmass a supercontinent?","It joins several continental plates into one vast landmass.","It is a single small island.","It is a deep ocean trench.","A supercontinent is a very large continent assembled from smaller continental plates."),Q("supercontinent.q2","supercontinent.s1","context","Which example is a supercontinent?","Pangaea, when Earth’s continents were joined together.","A coral atoll surrounded by a lagoon.","A narrow river delta.","Pangaea represents a huge joined landmass, unlike a small island or delta."),Q("supercontinent.q3","supercontinent.s1","word-choice","Choose the accurate description.","A supercontinent can later break apart as plates move.","A supercontinent is always smaller than a city.","A supercontinent is a group of unrelated stars.","Plate motion can assemble and later split a supercontinent."),Q("supercontinent.q4","supercontinent.s1","meaning","Why is the word “supercontinent” useful in geology?","It names an unusually large joined continental landmass.","It names the deepest layer of the atmosphere.","It means a continent with a very tall mountain only.","The term captures a scale and assembly beyond an ordinary continent.")]);
P('superficial','From Latin superficialis “of the surface,” from superficies, formed from super- “above” + facies “face.”',[C("superficial.s1","medicine","The doctor found only a superficial cut; it had not reached the deeper tissue.","醫生發現那只是表皮的割傷，尚未傷及較深層組織。","A superficial injury affects the outside only.","The adjective precedes and modifies cut.","The example uses the physical surface sense, not the figurative sense of shallow thought."),C("superficial.s2","education","Her superficial reading missed the argument that connected the two chapters.","她粗略的閱讀沒有注意到連結兩章的論點。","A superficial examination is not serious or deep.","The adjective modifies reading and describes its lack of depth.","The figurative sense concerns shallow thinking or study.")],[M("The surgeon called the wound superficial after it had cut through muscle and bone.","The surgeon called the wound deep after it had cut through muscle and bone.","A wound reaching muscle and bone is not superficial; superficial means only the outer layer.")],[Q("superficial.q1","superficial.s1","meaning","A superficial scratch affects which part?","Only the outer surface.","The deepest internal tissue.","The bone beneath every layer.","The physical sense means affecting only the outside."),Q("superficial.q2","superficial.s2","meaning","What is a superficial review of an argument?","A quick, shallow review that misses deeper reasoning.","A careful analysis of every premise.","A review conducted beneath the floor.","The figurative sense means not studying or thinking in a serious, deep way."),Q("superficial.q3","superficial.s1","context","Which finding is most likely superficial?","A scrape limited to the skin’s outer layer.","A fracture deep inside the bone.","A torn ligament beneath the joint.","An outer-layer scrape fits the physical surface sense."),Q("superficial.q4","superficial.s2","distinction","Why might a superficial explanation be inadequate?","It may skip the important underlying reasons.","It is always written on the surface of water.","It necessarily contains too many details.","A superficial explanation lacks serious depth and can miss the central reasoning.")]);
P('superficiality','Formed from superficial + -ity, a noun-forming suffix; superficial derives from Latin superficialis “of the surface.”',[C("superficiality.s1","media","The article criticized the superficiality of reviews that praised the film’s costumes but ignored its story.","文章批評了那些只稱讚電影服裝、卻忽略故事的影評之淺薄。","Superficiality is a lack of depth in thought or treatment.","The abstract noun is the object of criticized; of reviews specifies where the quality appeared.","The example contrasts surface impressions with deeper analysis.")],[M("The essay’s superficiality came from its careful analysis of every cause and consequence.","The essay’s depth came from its careful analysis of every cause and consequence.","Careful analysis of causes and consequences shows depth, not superficiality.")],[Q("superficiality.q1","superficiality.s1","meaning","What does superficiality in a review mean?","It lacks depth and focuses only on surface features.","It explains every important idea in detail.","It measures the review’s physical length only.","Superficiality is a lack of depth in thought or treatment."),Q("superficiality.q2","superficiality.s1","context","Which criticism points to superficiality?","The report lists slogans but never examines their consequences.","The report tests each claim against evidence.","The report explains both causes and effects.","Listing slogans without analysis is shallow treatment."),Q("superficiality.q3","superficiality.s1","distinction","Which quality is the opposite of superficiality?","Depth of thought.","A glossy cover.","A brief title.","Superficiality is lack of depth, so thoughtful depth contrasts with it."),Q("superficiality.q4","superficiality.s1","meaning","Why might a teacher object to an essay’s superficiality?","It may mention a topic without developing its ideas.","It uses a readable font.","It has exactly four paragraphs.","A superficial treatment lacks serious depth or development.")]);
P('superficially','Formed from superficial + -ly; superficial traces to Latin superficialis “of the surface.”',[C("superficially.s1","science","The two samples look superficially similar, but their chemical compositions differ.","這兩個樣本表面上看起來相似，但化學成分不同。","Superficially means in outward appearance or after only a quick look.","The adverb modifies similar and limits the comparison to appearance.","The example warns that a surface resemblance does not establish deeper identity.")],[M("The samples were superficially identical in every hidden chemical detail.","The samples were superficially similar in appearance but differed in hidden chemical details.","Superficially limits the claim to outward appearance; it cannot guarantee identity in hidden details.")],[Q("superficially.q1","superficially.s1","meaning","If two objects are superficially similar, how are they similar?","They look alike on the outside or at first glance.","They are identical in every hidden property.","They are physically underneath one another.","The adverb concerns only the outside or a quick look."),Q("superficially.q2","superficially.s1","context","Which sentence uses “superficially” correctly?","The plans are superficially alike but have different costs.","The plans superficially cost the same because they were buried.","She superficially the plan yesterday.","The adverb marks an outward similarity that may not hold in detail."),Q("superficially.q3","superficially.s1","distinction","What does a superficial inspection do superficially?","Checks only the appearance or obvious features.","Verifies every concealed component.","Changes an object into a liquid.","A superficial look is quick and limited to the outside."),Q("superficially.q4","superficially.s1","word-choice","Which contrast matches “superficially similar”?","Similar in appearance, different in deeper structure.","Different in appearance, identical in every respect.","Both entirely invisible.","The adverb allows a surface resemblance while deeper properties differ.")]);
P('superfluous','From Latin superfluus “overflowing, excessive,” from super- “over” + fluere “flow.”',[C("superfluous.s1","editing","After the figures were checked, the editor removed a superfluous table that repeated the same data.","數據核對後，編輯刪除了重複相同資料的多餘表格。","Superfluous means more than is needed or wanted.","The adjective modifies table; the relative clause explains why it was unnecessary.","The example uses the quantity sense: the repeated table adds nothing needed."),C("superfluous.s2","conversation","His superfluous remark interrupted the meeting without adding anything useful.","他那句多餘的話打斷了會議，卻沒有帶來任何有用內容。","A superfluous remark is unnecessary and may be annoying.","The adjective modifies remark in a noun phrase.","The second sense highlights unnecessary speech that irritates or distracts.")],[M("The duplicate chart was superfluous because the report lacked any other table.","The duplicate chart was superfluous because it repeated a table already in the report.","A duplicate chart is unnecessary when it repeats existing material; lack of other tables would not explain that judgment.")],[Q("superfluous.q1","superfluous.s1","meaning","What is a superfluous item?","One that is more than needed.","One that is essential and missing.","One that is impossible to count.","Superfluous means more than is needed or wanted."),Q("superfluous.q2","superfluous.s2","context","Which remark is superfluous in a meeting?","A needless interruption that adds no information.","A concise answer to the chair’s question.","A safety warning everyone needs to hear.","The source’s second sense describes unnecessary and annoying speech."),Q("superfluous.q3","superfluous.s1","word-choice","A designer removes a superfluous button. What does that imply?","The button was unnecessary for the design.","The button was the only way to use the device.","The button was a replacement employee.","Removing a superfluous element removes something not needed."),Q("superfluous.q4","superfluous.s2","distinction","Why can a superfluous comment be unwelcome?","It is unnecessary and may distract or annoy people.","It supplies a required fact.","It is the meeting’s official title.","The second sense emphasizes needless speech that can be annoying.")]);
P('superheat','Formed from super- “beyond, excessively” + heat. In thermodynamics, superheat raises vapor above its boiling-point temperature.',[C("superheat.s1","thermodynamics","The technician adjusted the boiler to superheat the steam above its saturation temperature.","技術員調整鍋爐，使蒸汽過熱到高於飽和溫度。","To superheat vapor is to raise it above the boiling point of its liquid.","The verb takes steam as its object; above introduces the reference temperature.","The technical sense is about vapor temperature, not simply making any object very hot.")],[M("The boiler superheated the steam by cooling it below its boiling point.","The boiler superheated the steam by raising it above its boiling point.","Superheating raises vapor above the liquid’s boiling-point temperature; cooling below it is the opposite.")],[Q("superheat.q1","superheat.s1","meaning","What happens when steam is superheated?","Its temperature rises above the liquid’s boiling point.","It is cooled until it condenses.","It is held exactly at room temperature.","Superheat means raise vapor above the boiling point of its liquid."),Q("superheat.q2","superheat.s1","context","Which process superheats vapor?","Heating steam beyond its saturation temperature.","Freezing water into ice.","Cooling steam until it becomes liquid.","The superheated state is above the boiling/saturation point."),Q("superheat.q3","superheat.s1","distinction","How does superheating differ from ordinary boiling?","The vapor is heated further after it has formed.","The liquid is chilled before boiling.","The substance is mixed with soil.","Superheat specifically describes vapor above its liquid’s boiling temperature."),Q("superheat.q4","superheat.s1","word-choice","A lab note says a vapor was superheated. Which measurement matters?","Its temperature relative to the liquid’s boiling point.","The color of the container only.","The name of the lab assistant.","The term is defined by temperature above the boiling point.")]);
P('superimpose','Formed from super- “over” + impose, from Latin imponere “put on.”',[C("superimpose.s1","cartography","The analyst superimposed the rainfall map on the city map to compare flood risk by neighborhood.","分析員將降雨圖疊加在城市地圖上，以比較各街區的洪水風險。","To superimpose is to lay one image or layer over another.","The verb takes the map as its object; on marks the layer beneath it.","The example makes the overlay relationship clear: two maps are aligned for comparison.")],[M("The analyst superimposed the rainfall map beside the city map, with no overlap.","The analyst placed the rainfall map over the city map so the layers overlapped.","Superimpose means place one image or layer over another, not simply beside it.")],[Q("superimpose.q1","superimpose.s1","meaning","What does it mean to superimpose one map on another?","Place one map over the other so their features can be compared.","Store each map in a separate room.","Erase both maps before comparing them.","Superimpose means lay one image or layer over another."),Q("superimpose.q2","superimpose.s1","context","Which action superimposes images?","Overlaying a transparent route map on a street map.","Putting two maps in separate folders.","Folding a map into a small square.","An overlay places one image over the other."),Q("superimpose.q3","superimpose.s1","collocation","Which phrase is natural?","superimpose a diagram on a photograph","superimpose a diagram under yesterday","superimpose to a photograph","The usual construction is superimpose one image on another."),Q("superimpose.q4","superimpose.s1","meaning","Why might a researcher superimpose two images?","To compare corresponding details in overlapping layers.","To make both images disappear.","To measure the age of a paper sheet.","Overlaid images let the researcher compare aligned features.")]);
P('superintend','From Latin superintendere “oversee,” from super- “over” + intendere “direct, stretch toward.”',[C("superintend.s1","management","A site engineer was appointed to superintend the bridge repairs and check each safety stage.","一名現場工程師受命監督橋梁修復，並檢查每個安全階段。","To superintend is to direct and watch a process, staff, or institution.","The verb takes repairs as its object; to check adds the supervisor’s monitoring role.","The example shows both direction and oversight, not merely attendance.")],[M("The engineer superintended the repairs by avoiding the site and checking no work.","The engineer superintended the repairs by visiting the site and checking the work.","Superintend means direct and watch a process; avoiding all oversight does not fit.")],[Q("superintend.q1","superintend.s1","meaning","What does an engineer do when she superintends repairs?","Directs the work and monitors its progress.","Pays for the materials but never checks the work.","Removes the bridge from the map.","Superintend means direct and watch a process."),Q("superintend.q2","superintend.s1","grammar","Choose the correct sentence.","She superintends the laboratory staff.","She superintend the laboratory staffs yesterday.","She is superintend the staff.","The third-person singular present form is superintends."),Q("superintend.q3","superintend.s1","distinction","How does superintend differ from simply attend?","It includes directing and monitoring the work.","It means being physically present with no responsibility.","It means taking over a title by inheritance.","Superintending involves oversight, not just presence."),Q("superintend.q4","superintend.s1","context","Which person is superintending a construction project?","The manager directing crews and checking each stage.","A visitor taking photos from the street.","A passerby who does not know the workers.","The manager exercises direction and oversight over the process.")]);
P('superintendent','From Latin superintendentem, present participle of superintendere “oversee”; regional senses include a senior police officer or apartment-building manager.',[C("superintendent.s1","education","The school superintendent approved the district-wide calendar after consulting principals.","學區主管與各校校長商議後，核准了全區行事曆。","A superintendent is a person in charge of a department, works, or activity.","The noun superintendent is the subject of approved.","This context uses the school-district leadership sense; regional usage also includes police and property roles.")],[M("The superintendent had no responsibility for the school district and could not direct any activity.","The superintendent was responsible for directing the school district’s activities.","A superintendent is a person in charge, not someone without authority.")],[Q("superintendent.q1","superintendent.s1","meaning","What does a school superintendent generally do?","Oversees or directs the school district.","Teaches only one classroom and has no wider duties.","Collects rent in every city apartment building.","The source sense is a person in charge of a department or activity."),Q("superintendent.q2","superintendent.s2","context","In a building notice, who may be called the superintendent?","The manager responsible for the apartment building.","A tenant visiting for one night.","A student who attends the school.","One source sense is a person who manages an apartment building."),Q("superintendent.q3","superintendent.s2","meaning","A police superintendent is most likely what?","A senior police officer.","A junior witness in court.","A private apartment tenant.","The source also uses superintendent as a senior police rank."),Q("superintendent.q4","superintendent.s1","distinction","What is central to the role of a superintendent?","Being in charge of a department, works, or activity.","Receiving an issue of a magazine regularly.","Having a merely superficial view of a project.","The core meaning is a person who directs or oversees an area of work.")]);
P('superior','From Latin superior “higher, above,” comparative of superus “situated above.” It can mean better in quality, a higher-ranking person, or an arrogant manner.','Latin superior, comparative of superus “above”','This model is superior to the older one in battery life and repairability.','這款機型在電池續航與可維修性方面優於舊款。','technology','Adjective sense 1: better than something, usually superior to; noun: a higher-ranking person; sense 3: an arrogant attitude.','The context uses the quality comparison; the source also includes rank and a disapproving attitude sense.',M('The new battery is superior than the old battery in every test.','The new battery is superior to the old battery in every test.','The adjective superior takes “to,” not “than,” in this comparison.','collocation'),[Q("superior.q1","superior.s1","collocation","Which construction is standard?","superior to the earlier design","superior than the earlier design","superior from the earlier design","Superior is followed by to when comparing quality."),Q("superior.q2","superior.s2","meaning","Your supervisor says “Ask your superior to sign.” Who is the superior?","A person with a higher position.","A product of better quality.","A person who manages a building only.","The noun sense is someone in a higher position."),Q("superior.q3","superior.s3","context","What does a superior tone suggest?","The speaker acts as if other people are beneath them.","The speaker is objectively taller.","The speaker is describing a better battery.","The third sense is showing that one thinks oneself better than others."),Q("superior.q4","superior.s1","distinction","Which sentence uses superior to mean better in quality?","The newer filter removes more particles than the old one.","The manager asked her superior for approval.","He spoke with a superior expression.","The first compares performance; the other choices use rank and attitude senses.")]);
P('superiority','Formed from superior + -ity; superior derives from Latin superior “higher, above.” It denotes being better or higher, and can also mean an arrogant feeling.',[C("superiority.s1","engineering","The test showed the newer pump’s superiority in efficiency, not merely in appearance.","測試顯示新款幫浦在效率上具有優勢，而不只是外觀不同。","Superiority is a state of being better or higher than others.","The noun is the object of showed; in efficiency names the dimension of comparison.","The example grounds the comparison in measurable performance."),C("superiority.s2","social behavior","His air of superiority made even helpful advice sound condescending.","他那種優越感使得即使是有益的建議聽起來也很居高臨下。","Superiority can mean a proud feeling of being better than others.","The phrase air of superiority names an attitude; made introduces its effect.","The second sense is a feeling or display of arrogance, not objective excellence.")],[M("Her superiority was a proud feeling that she was less capable than everyone else.","Her inferiority was a feeling that she was less capable than everyone else.","Feeling less capable is inferiority, the opposite of superiority.")],[Q("superiority.q1","superiority.s1","meaning","What did the pump demonstrate by its superiority in efficiency?","It performed better than the compared pumps.","It was physically placed above the laboratory.","It made the operators feel embarrassed.","Superiority can be the state of being better than others."),Q("superiority.q2","superiority.s2","context","What is an air of superiority?","A proud attitude that one is better than other people.","A measured increase in product efficiency.","A weather current above a mountain.","The second sense describes a proud feeling of being better than others."),Q("superiority.q3","superiority.s1","collocation","Which phrase fits objective comparison?","superiority in durability","superiority to feel proud","superiority among under the table","The noun naturally takes “in” to name the area of an advantage."),Q("superiority.q4","superiority.s2","distinction","Why might others dislike a display of superiority?","It can make the speaker seem arrogant or condescending.","It proves that the speaker has better test data.","It means the speaker is a supervisor.","The attitude sense can communicate arrogance toward other people.")]);
P('supermarket','Formed from super- “large, above ordinary” + market; the modern self-service store sense became common in the twentieth century.','super- + market','We bought rice, vegetables, and soap at the supermarket on the corner.','我們在街角的超級市場買了米、蔬菜和肥皂。','shopping','Noun: a large self-service shop selling food and household goods.','The example lists the kinds of goods sold in the source sense.',M('The supermarket sold only one handmade ring and no food or household goods.','The jewelry shop sold one handmade ring; the supermarket stocked food and household goods.','A supermarket is a large self-service store with food and household items, not a single-item jewelry shop.','meaning'),[Q("supermarket.q1","supermarket.s1","meaning","What kind of place is a supermarket?","A large self-service shop for food and household goods.","A hospital department for surgery.","A tiny stall selling one newspaper.","The headword names a large self-service shop with food and household products."),Q("supermarket.q2","supermarket.s1","context","Where would someone most likely buy both apples and laundry soap?","At a supermarket.","At a one-item bakery.","At a courthouse.","Supermarkets commonly sell food and household goods."),Q("supermarket.q3","supermarket.s1","distinction","What feature often distinguishes a supermarket from a small counter shop?","Customers select many goods themselves from aisles.","It sells only one type of imported spice.","It is always located below ground.","The source sense describes a large self-service shop."),Q("supermarket.q4","supermarket.s1","word-choice","Choose the natural sentence.","They stopped at the supermarket to buy groceries.","They supermarketed the groceries carefully.","The supermarket was a person who supervised the school.","The word is a countable noun for a grocery and household-goods store.")]);
P('supermodel','Formed from super- “exceptionally notable” + model, a person who displays clothing or products.','super- + model','The supermodel appeared on international magazine covers and led major runway shows.','這位超級模特登上國際雜誌封面，並領銜多場大型伸展台秀。','fashion','Noun: a supermodel is a model with international celebrity beyond ordinary runway work.','The context signals the high-profile celebrity sense, rather than any person modeling a product.',M('The anonymous person who posed once for a local catalog was automatically a supermodel.','The anonymous person who posed once for a local catalog was a model, not necessarily a supermodel.','A supermodel has international celebrity beyond ordinary modeling work.','distinction'),[Q("supermodel.q1","supermodel.s1","meaning","What usually sets a supermodel apart from an ordinary model?","International celebrity and major public recognition.","A job modeling one product once.","A role directing a school district.","The source definition emphasizes celebrity beyond ordinary runway work."),Q("supermodel.q2","supermodel.s1","context","Which person best fits “supermodel”?","A globally famous runway figure featured on major covers.","A shop customer trying on a coat.","A photographer who never models clothing.","Global fame and high-profile runway work match the term."),Q("supermodel.q3","supermodel.s1","distinction","Does every clothing model count as a supermodel?","No; the word suggests exceptional celebrity and prominence.","Yes; anyone wearing a coat is one.","No; it means a person who repairs computers.","The prefix marks a particularly prominent, internationally known model."),Q("supermodel.q4","supermodel.s1","word-choice","Which sentence uses the noun naturally?","The supermodel walked in the charity fashion show.","The supermodelly walked the show.","They supermodel the runway yesterday.","Supermodel is a countable noun naming a high-profile fashion model.")]);
P('supernatural','Formed from super- “beyond” + natural, from Latin naturalis “by birth, according to nature.”','super- “beyond” + natural','The novel’s supernatural events cannot be explained by ordinary scientific laws.','小說中的超自然事件無法用一般科學定律解釋。','literature','Adjective: supernatural forces, events, or beings seem to come from beyond scientific nature.','The example refers to powers outside ordinary natural explanation, not merely unusual events.',M('The supernatural eclipse was fully predicted and explained by ordinary orbital mechanics.','The natural eclipse was fully predicted and explained by ordinary orbital mechanics.','An event explained by ordinary natural laws is not supernatural in the stated sense.','distinction'),[Q("supernatural.q1","supernatural.s1","meaning","What makes an event supernatural in a story?","It seems to come from powers outside ordinary scientific nature.","It is unusual but fully explained by ordinary physics.","It happens every morning at sunrise.","Supernatural refers to gods, spirits, or powers beyond scientific nature."),Q("supernatural.q2","supernatural.s1","context","Which plot event is most clearly supernatural?","A spirit moves an object without any natural cause.","A storm forms as warm air rises.","A light bulb breaks after years of use.","The spirit’s unexplained action invokes a power outside natural explanation."),Q("supernatural.q3","supernatural.s1","distinction","Is an ordinary solar eclipse supernatural?","No; astronomy explains it through the motion of the Sun, Moon, and Earth.","Yes; every shadow is caused by a ghost.","Yes; it is always outside the laws of nature.","A predictable astronomical event has an ordinary scientific explanation."),Q("supernatural.q4","supernatural.s1","word-choice","Choose the natural phrase.","a supernatural presence in the haunted house","a supernatural sandwich for lunch","to supernatural the old machine","The adjective modifies a noun such as presence or event.")]);
P('supernova','Formed from super- + nova, Latin nova “new [star].” Astronomers use it for a star’s explosive outburst near the end of its life.','super- + nova, Latin nova “new star”','The telescope recorded a supernova whose light had traveled for millions of years.','望遠鏡記錄到一顆超新星，其光線已經行進數百萬年。','astronomy','Noun: a supernova is a stellar explosion or the object observed during it.','The source sense includes both the explosion and the astronomical object seen during the event.',M('Astronomers called the steady, unchanged glow of an ordinary star a supernova.','Astronomers called the star’s enormous explosive outburst a supernova.','A supernova is an explosive stellar event, not a steady unchanged glow.','meaning'),[Q("supernova.q1","supernova.s1","meaning","What is a supernova?","An enormous stellar explosion near the end of a star’s life.","A planet reflecting sunlight.","A star that never changes or emits light.","The source defines a supernova as a star’s explosion or the object observed during it."),Q("supernova.q2","supernova.s1","context","Which observation could reveal a supernova?","A distant star suddenly brightens in a powerful explosive event.","A planet completes its ordinary daily orbit.","A telescope lens is cleaned.","A supernova is a stellar outburst, not an ordinary orbit."),Q("supernova.q3","supernova.s1","word-choice","Which object is being discussed in “The supernova faded over several weeks”?","The observed stellar explosion and its light.","A grocery store’s new sign.","A sound traveling faster than light.","Supernova names the star’s explosive event or the observed object."),Q("supernova.q4","supernova.s1","distinction","How is a supernova different from a normal star shining steadily?","It is a dramatic explosive event in a star’s life.","It is a moon orbiting a planet.","It is a type of underground passage.","The explosion is the defining astronomical event.")]);
P('superorganism','Formed from super- “above, beyond” + organism, from Greek organon “instrument, organ.”','super- + organism, from Greek organon “organ”','An ant colony can function as a superorganism when its members cooperate like parts of one living system.','當蟻群成員像單一生命系統的各部分般合作時，整個群體可作為超個體運作。','biology','Noun: a superorganism is a cooperating group whose colony behaves like one living thing.','The context emphasizes coordinated behavior across organisms, not a single unusually large individual.',M('A lone ant in a jar is a superorganism because it lives by itself.','A coordinated ant colony may act as a superorganism because its members cooperate as one system.','The term describes a group of cooperating organisms, not one isolated animal.','meaning'),[Q("superorganism.q1","superorganism.s1","meaning","What is a superorganism?","A cooperating group that behaves like one living thing.","A single organism that has grown unusually large.","A collection of unrelated fossils.","A colony can behave as one system through close cooperation."),Q("superorganism.q2","superorganism.s1","context","Which example best fits the term?","A termite colony with specialized members coordinating its survival.","One isolated beetle in a jar.","A pile of stones shaped like insects.","The term needs a group whose members cooperate as one living system."),Q("superorganism.q3","superorganism.s1","distinction","Why might a bee colony be called a superorganism?","Its members perform coordinated roles that support the colony as a whole.","Every bee is biologically identical to a human organ.","The colony is a single giant bee.","The analogy is functional cooperation, not literal identity or size."),Q("superorganism.q4","superorganism.s1","word-choice","Which sentence uses “superorganism” correctly?","Researchers studied how the colony functioned as a superorganism.","The superorganism was a single unusually tall flower.","They superorganismed the data.","The noun names a group of organisms acting as one system.")]);
P('supersede','From Latin supersedere “sit above, refrain,” from super- “above” + sedere “sit”; English spelling reflects later confusion with verbs in -cede. The modern sense is to replace something earlier.','Latin supersedere “sit above; refrain”','The revised safety code will supersede the outdated rules next month.','修訂後的安全規範將於下個月取代過時規定。','law','Verb: supersede a rule, document, or person by taking its place.','This sentence uses the replacement sense; a superseding regulation makes the previous one no longer current.',M('The new regulation superseded the old one, but the old one remained the only rule in force.','The new regulation superseded the old one, so the old one was no longer in force.','To supersede is to take the earlier rule’s place; both cannot remain the sole rule in force.','meaning'),[Q("supersede.q1","supersede.s1","meaning","What happens when a new rule supersedes an old rule?","The new rule takes the old rule’s place.","The old rule becomes more authoritative.","Both rules disappear without replacement.","Supersede means replace something that existed before."),Q("supersede.q2","supersede.s2","context","A signed amendment supersedes a previous clause. What changes?","The previous clause no longer has force.","The amendment becomes a supermarket receipt.","The clause is made more difficult to read only.","The document sense specifically replaces a prior decision or agreement so it is no longer effective."),Q("supersede.q3","supersede.s1","spelling","Which spelling is correct for “replace an older system”?","supersede","supercede","supersced","The standard spelling is supersede, despite its sound resembling -cede verbs."),Q("supersede.q4","supersede.s1","distinction","Which event is an example of one policy superseding another?","A new policy formally replaces the old policy.","A new policy is discussed but never adopted.","An old policy is copied into a notebook.","Superseding requires taking the earlier policy’s place.")]);
P('supersonic','Formed from super- “beyond” + sonic, from Latin sonus “sound.”','super- “beyond” + sonic, from Latin sonus “sound”','The test aircraft crossed the sound barrier during a supersonic flight.','測試飛機在超音速飛行期間突破了音障。','aviation','Adjective sense 1: faster than sound; sense 2: relating to flight at that speed.','The context uses the flight sense; the underlying speed is greater than the speed of sound.',M('The supersonic jet flew at 300 kilometers per hour, far below the speed of sound.','The subsonic jet flew at 300 kilometers per hour, far below the speed of sound.','Supersonic means faster than sound; a speed far below it is subsonic.','measurement'),[Q("supersonic.q1","supersonic.s1","meaning","How fast is a supersonic aircraft traveling?","Faster than the speed of sound.","Slower than a walking person.","Exactly at the speed of a bicycle.","Supersonic means faster than sound."),Q("supersonic.q2","supersonic.s2","context","What is a supersonic flight?","A flight involving travel faster than sound.","A flight that never leaves the runway.","A flight beneath the ocean floor.","The second source sense is relating to flight at supersonic speed."),Q("supersonic.q3","supersonic.s1","distinction","What boundary does an aircraft cross to become supersonic?","The speed of sound in the surrounding air.","The freezing point of water.","The edge of a city suburb.","Supersonic is defined relative to the speed of sound."),Q("supersonic.q4","supersonic.s2","word-choice","Which phrase is natural?","supersonic flight","supersonic to the airport","flight supersonically aircraft","Supersonic is an adjective modifying flight or aircraft.")]);
P('superstition','From Old French superstition, from Latin superstitionem; the deeper Latin origin is uncertain, so no root breakdown is asserted.','Old French superstition, from Latin superstitionem; deeper origin uncertain','The belief that a black cat guarantees bad luck is a superstition, not scientific evidence.','認為黑貓一定帶來厄運是一種迷信，並非科學證據。','culture','Noun: a superstition is an irrational belief that magic or luck controls events.','The example states an unsupported cause-and-effect belief based on luck.',M('She called checking a measured weather forecast a superstition because it used reliable data.','She called believing a charm controls the weather a superstition because it relies on luck rather than evidence.','A rational forecast based on data is not superstition; the term describes belief in magic or luck without rational basis.','distinction'),[Q("superstition.q1","superstition.s1","meaning","What is a superstition?","A belief that magic or luck controls events without a rational basis.","A conclusion established through repeated controlled tests.","A legal rule passed by a legislature.","The source defines superstition as an irrational belief in magic or luck."),Q("superstition.q2","superstition.s1","context","Which belief is a superstition?","Wearing a lucky sock will guarantee a job offer.","Preparing for an interview improves readiness.","Checking the interview time prevents arriving late.","The lucky sock claim assigns control to luck without rational evidence."),Q("superstition.q3","superstition.s1","distinction","Why is superstition different from a tested scientific claim?","It relies on magic or luck without a rational evidential basis.","It is always more carefully measured.","It is a kind of supermarket receipt.","The word marks unsupported belief, unlike claims tested against evidence."),Q("superstition.q4","superstition.s1","word-choice","Which phrase is natural?","an old superstition about breaking a mirror","a superstition of a microscope measured the sample","to superstition the result","Superstition is a countable noun for an irrational belief.")]);
P('superstitious','Formed from superstition + -ious; superstition comes through Old French from Latin superstitionem.','superstition + -ious; Latin superstitionem, deeper origin uncertain','He felt superstitious and avoided starting the trip on Friday the thirteenth.','他有些迷信，因此避免在十三號星期五出發。','culture','Adjective sense 1: believing magic or luck controls events; sense 2: an act done because of such a belief.','The context uses the believer sense; the adjective can also characterize behavior motivated by superstition.',M('Her superstitious decision was based entirely on a randomized controlled trial and no belief in luck.','Her evidence-based decision was based entirely on a randomized controlled trial and no belief in luck.','A decision based solely on controlled evidence is not superstitious; the word concerns belief in magic or luck.','distinction'),[Q("superstitious.q1","superstitious.s1","meaning","What makes someone superstitious?","They believe magic or luck controls events.","They reject all ideas of luck or magic.","They only study grammar.","Superstitious describes belief that magic and luck control events."),Q("superstitious.q2","superstitious.s2","context","Which action is superstitious in the behavior sense?","A player wears a lucky shirt because they think it causes a win.","A player checks the field conditions before a game.","A player follows the coach’s evidence-based plan.","The action is done because of an unreasonable belief about luck."),Q("superstitious.q3","superstitious.s1","distinction","Is every cautious person superstitious?","No; caution can be based on evidence rather than magic or luck.","Yes; caution always involves a lucky charm.","No; the word describes only a kind of clothing.","Superstitious requires belief in luck or magic controlling events."),Q("superstitious.q4","superstitious.s2","word-choice","Which phrase uses the behavior sense?","a superstitious ritual before the match","a superstitious belief that luck controls events","a superstitious person who trusts no omens","The ritual is an act done because of a superstitious belief.")]);
P('superstructure','From super- “above” + structure, from Latin structura “a building, arrangement,” from struere “build.”','super- “above” + structure, from Latin structura “building”','Engineers inspected the bridge’s superstructure after checking the underwater piers.','工程師檢查水下橋墩後，檢視了橋梁的上部構造。','engineering','Noun: a superstructure is the part built above a foundation, deck, or supporting base.','The example contrasts the upper construction with the bridge’s underwater piers and foundation.',M('The bridge’s superstructure was buried deep below its foundation.','The bridge’s substructure was buried below its superstructure.','A superstructure is built above its base; the part below is the substructure.','distinction'),[Q("superstructure.q1","superstructure.s1","meaning","What is a bridge superstructure?","The structure built above the supporting foundation or deck.","The soil beneath every pier.","A temporary traffic detour.","The source sense places the superstructure above a foundation or base."),Q("superstructure.q2","superstructure.s1","context","Which part is most likely the superstructure?","The deck and upper frame carried above the bridge supports.","The deep footing below the riverbed.","The river channel beneath the bridge.","The upper deck and frame are built above the foundation."),Q("superstructure.q3","superstructure.s1","distinction","What is the relation between superstructure and substructure?","The superstructure is above; the substructure is below.","Both mean underground foundation.","The superstructure is always smaller than a bolt.","The prefix super- places the structure above its supporting base."),Q("superstructure.q4","superstructure.s1","word-choice","Which field commonly uses “superstructure” for the top of a bridge?","Civil engineering.","Baking bread.","Writing a poem’s subtitle.","Engineers use the term for construction above the foundation or deck.")]);
P('supervise','From Medieval Latin supervisere “oversee,” from super- “over” + videre “see.”','Medieval Latin supervisere “oversee,” from super- + videre “see”','A laboratory manager will supervise the trainees while they handle the chemical samples.','實驗室主管會在受訓人員處理化學樣本時監督他們。','laboratory','Verb sense 1: watch a person or activity to ensure correct work; sense 2: be in charge of workers.','The context combines observation and responsibility for correct procedure.',M('The manager supervised the trainees by leaving them alone with no instructions or checks.','The manager supervised the trainees by giving instructions and checking their work.','Supervise includes watching and making sure work is done correctly.'),[Q("supervise.q1","supervise.s1","meaning","What does a manager do when she supervises trainees?","Watches their work and checks that it is done correctly.","Avoids all contact with them.","Writes a title for their report.","To supervise is to watch people or activities and ensure correctness."),Q("supervise.q2","supervise.s2","context","Which manager is supervising a team?","The person in charge who directs workers during a shift.","A customer waiting outside the building.","A former employee with no duties.","The second sense means being in charge of people while they work."),Q("supervise.q3","supervise.s1","grammar","Choose the correct sentence.","The nurse supervises the medication round.","The nurse supervise the round yesterday.","The nurse is supervise the round.","The third-person singular present form is supervises."),Q("supervise.q4","supervise.s1","distinction","How does supervising differ from simply observing?","It includes checking that the activity is done properly.","It means looking without any responsibility.","It means replacing a written rule.","Supervision adds oversight and responsibility to watching.")]);
P('supervision','From Latin supervisionem, from supervisere “oversee.” It can denote oversight or regular academic guidance.','Latin supervisionem, from supervisere “oversee”','The site remained open only under adult supervision.','現場只有在成人監督下才會開放。','safety','Noun sense 1: oversight to ensure rules are followed; sense 2: regular teaching and guidance from a tutor.','This context uses safety oversight; academic supervision is a separate source sense.',M('The children were under supervision, but no adult watched them or checked their safety.','The children were unsupervised because no adult watched or checked their safety.','Supervision means someone watches and ensures rules or safety are followed.'),[Q("supervision.q1","supervision.s1","meaning","What does adult supervision provide at a work site?","Someone watches and helps ensure rules are followed.","A guarantee that no one needs safety rules.","A list of magazine subscriptions.","Supervision is the act of watching people or places to ensure rules are followed."),Q("supervision.q2","supervision.s2","context","A graduate student meets weekly with a thesis tutor for guidance. What is this?","Academic supervision.","Police supervision.","A supper invitation.","The second source sense is a tutor’s regular teaching and guidance."),Q("supervision.q3","supervision.s1","collocation","Which phrase is natural?","under close supervision","in supervision for a title","supervision at to the room","The standard phrase is under supervision."),Q("supervision.q4","supervision.s2","distinction","How can a tutor’s supervision help a student?","It provides regular teaching and guidance on a project.","It replaces the student’s thesis with a rulebook.","It ensures the student eats a late meal.","Academic supervision is guidance from a tutor through a project or thesis.")]);
P('supervisor','From Latin supervisor, agent noun from supervisere “oversee.” The noun can name a workplace manager or an academic tutor.','Latin supervisor, from supervisere “oversee”','The shift supervisor checked the equipment before the factory opened.','工廠開門前，值班主管檢查了設備。','workplace','Noun sense 1: a manager who checks workers’ tasks; sense 2: a tutor guiding a student project or thesis.','The example uses the workplace role; the source also includes the academic-adviser role.',M('The supervisor was responsible for the shift but never managed workers or checked their work.','The supervisor managed the shift and checked that workers completed their tasks.','A supervisor manages workers and checks that work is done properly.'),[Q("supervisor.q1","supervisor.s1","meaning","What is a shift supervisor expected to do?","Manage workers and check that their work is done properly.","Wait as a customer with no duties.","Write the thesis for every student.","The workplace sense is a person who manages workers and checks their work."),Q("supervisor.q2","supervisor.s2","context","Who is a thesis supervisor?","A tutor who guides a student through a research project.","A building tenant who pays rent.","A cashier working at a supermarket.","The academic sense is a tutor guiding a student’s thesis or project."),Q("supervisor.q3","supervisor.s1","distinction","Why might a team ask its supervisor to review a safety checklist?","The supervisor is responsible for checking how work is done.","The supervisor is always the newest worker.","The supervisor is a type of safety helmet.","The role includes managing workers and checking their tasks."),Q("supervisor.q4","supervisor.s2","word-choice","Which phrase uses the academic sense?","Her supervisor advised her on the thesis draft.","The supervisor checked the night crew’s time cards.","The supervisor directed the school district calendar.","A thesis draft and advising point to the tutor sense.")]);
P('supervisory','Formed from supervise + -ory, from Latin supervisere “oversee.”','supervise + -ory; supervise from Latin supervisere “oversee”','The new policy gives supervisory staff responsibility for reviewing safety reports.','新政策要求主管人員負責審查安全報告。','workplace','Adjective: supervisory duties or staff are connected with checking and directing work.','It describes a role involving oversight, rather than ordinary participation only.',M('The supervisory team had no authority to check or direct any work.','The supervisory team had authority to check and direct the work.','Supervisory is connected with checking and directing how work is done.'),[Q("supervisory.q1","supervisory.s1","meaning","What are supervisory duties?","Tasks involving checking and directing how work is done.","Tasks involving only buying lunch.","Tasks performed below ground.","Supervisory means connected with oversight and direction."),Q("supervisory.q2","supervisory.s1","context","Which role is supervisory?","A lead worker who reviews quality and guides the team.","A visitor who watches once from the lobby.","A supplier delivering a package.","Reviewing quality and guiding workers are supervisory tasks."),Q("supervisory.q3","supervisory.s1","word-choice","Choose the natural phrase.","supervisory responsibility","supervisory to responsibility","responsibility supervisorially team","The adjective modifies responsibility directly."),Q("supervisory.q4","supervisory.s1","distinction","Does “supervisory” mean every task is done personally by a manager?","No; it concerns checking and directing the work of others.","Yes; it means the manager performs every task alone.","No; it means the work is a late meal.","Supervisory describes oversight, not necessarily doing all work oneself.")]);
P('supper','From Old French soper “to eat the evening meal,” related to soupe. It names an evening meal and, in another sense, a small late-night meal.','Old French soper “eat the evening meal,” related to soupe','We invited the neighbors over for supper at seven.','我們邀請鄰居七點來吃晚餐。','food','Noun sense 1: the evening meal; sense 2: a small meal eaten late at night.','This is the ordinary evening meal sense; a late-night snack is another sense.',M('They ate supper at dawn before beginning the evening.','They ate supper in the evening after the day’s work.','Supper is an evening meal, not a meal at dawn.'),[Q("supper.q1","supper.s1","meaning","When is supper ordinarily eaten?","In the evening.","At breakfast time before dawn.","Only at lunchtime.","Supper is the meal eaten in the evening."),Q("supper.q2","supper.s2","context","A guest has a small meal shortly before bed at 11 p.m. What might it be called?","A late supper.","A midday lunch.","A breakfast buffet.","The second sense is a small meal eaten late in the evening."),Q("supper.q3","supper.s1","word-choice","Which invitation uses “supper” naturally?","Come over for supper after work.","Come over for supper at sunrise breakfast.","Come over supperly after work.","The noun commonly names an evening meal shared after the day’s work."),Q("supper.q4","supper.s2","distinction","How does supper differ from a late-night snack in the source entry?","Supper can be the regular evening meal; a second sense is a smaller late meal.","Supper always means a midday drink.","They both mean the kitchen itself.","The source distinguishes a general evening meal from a small meal eaten late.")]);
P('supplant','From Latin supplantare “trip up, overthrow,” from sub- “under” + planta “sole of the foot.” It now means take over a role or replace an older thing.','Latin supplantare “trip up, overthrow”','Electric buses are beginning to supplant diesel vehicles on the city’s busiest routes.','電動公車正開始取代市區最繁忙路線上的柴油車。','transportation','Verb sense 1: take over someone’s job or position; sense 2: replace an older, weaker, or less useful thing.','The context uses the replacement-of-things sense; supplant can also mean take someone’s role.',M('The new payment app supplanted the old system while leaving the old system as the only one in use.','The new payment app supplanted the old system and took its place.','To supplant means replace; the old system cannot remain the only one in use.'),[Q("supplant.q1","supplant.s1","meaning","What does it mean to supplant a manager?","Take over the job or position the manager held.","Give the manager a larger office but no change in role.","Observe the manager without interacting.","The first source sense is taking over someone’s position."),Q("supplant.q2","supplant.s2","context","What happened when digital tickets supplanted paper tickets?","Digital tickets replaced the older paper system.","Paper tickets became more common again.","The tickets were placed beneath a bridge.","The second sense means replace something older or less useful."),Q("supplant.q3","supplant.s2","distinction","Which change is supplanting an old tool?","A newer tool takes its place because it works better.","The old tool is polished and kept unchanged.","The tool is placed beside the new one for display.","Supplant requires replacement, not preservation or simple adjacency."),Q("supplant.q4","supplant.s1","collocation","Which sentence uses the role sense?","She supplanted the retiring captain as team leader.","She supplemented the captain with a new report.","She superseded the captain’s paperwork only.","Supplant someone as a role-holder means take over the job or position.")]);
P('supple','From Old French souple “pliant, flexible,” ultimately from Latin supplex “bending, submissive.” As a verb, supple means make less stiff.','Old French souple “pliant, flexible,” from Latin supplex','After warming up, the dancer’s supple shoulders moved through the sequence without stiffness.','熱身後，舞者柔軟的肩膀毫不僵硬地完成了整套動作。','dance','Adjective sense 1: able to bend or move easily; verb sense 2: make skin, leather, or a body less stiff.','This example uses the flexible-adjective sense; the entry also records a verb meaning to make supple.',M('The supple leather was rigid and could not bend at all.','The stiff leather was rigid and could not bend at all.','Supple means flexible and able to bend easily; rigid leather is not supple.'),[Q("supple.q1","supple.s1","meaning","What is a supple body able to do?","Bend and move easily without stiffness.","Remain completely rigid.","Break apart when touched.","Supple describes flexibility and easy movement."),Q("supple.q2","supple.s2","context","What does a leather worker do to supple leather?","Makes the leather less stiff and more flexible.","It paints a new title on the leather.","It freezes the leather solid.","The verb sense is to make skin, leather, or a body less stiff."),Q("supple.q3","supple.s1","context","Which object is supple?","A flexible reed that bends in the breeze and returns to shape.","A brittle stick that snaps immediately.","A stone block that cannot bend.","The adjective describes something able to bend and move easily."),Q("supple.q4","supple.s1","distinction","Why might a dancer value supple muscles?","They allow flexible movement with less stiffness.","They prevent any movement at all.","They make a dancer a building supervisor.","Suppleness supports easy bending and motion.")]);
P('supplement','From Latin supplementum “that which fills up,” from supplere “complete, supply.” It can be an added item, a nutrient product, or the act of adding.','Latin supplementum “that which fills up,” from supplere “complete”','The handbook includes a supplement with updated maps and contact details.','手冊附有一份增補資料，內含更新後的地圖和聯絡方式。','publishing','Noun sense 1: added material that improves or completes; sense 2: a nutrient product; verb sense 3: add something extra.','The context uses the added-publication sense; supplements can also be dietary products or the act of adding.',M('The handbook’s supplement removed all maps and left the guide less complete.','The handbook’s supplement added updated maps and made the guide more complete.','A supplement is added to improve or complete something, not remove its useful parts.'),[Q("supplement.q1","supplement.s1","meaning","What is a supplement to a handbook?","Extra material added to improve or complete it.","A replacement that removes the handbook.","A person who manages the library.","A supplement is something added to complete or improve another thing."),Q("supplement.q2","supplement.s2","context","A person takes vitamin D in addition to meals. What is the product?","A dietary supplement.","A book appendix.","A substitute teacher.","The second sense is a product such as vitamins taken in addition to food."),Q("supplement.q3","supplement.s3","grammar","Which sentence uses “supplement” as a verb?","They supplemented the report with new survey results.","The supplement contained a map.","She took a supplement with breakfast.","Supplemented is a verb meaning added something extra."),Q("supplement.q4","supplement.s1","distinction","Why might a newspaper publish a weekend supplement?","It adds material to the regular paper.","It replaces every reader with a new one.","It removes the newspaper’s main sections.","A supplement is extra material provided in addition to the main item.")]);
P('supplementary','Formed from supplement + -ary; supplement comes from Latin supplementum “that which fills up.”','supplement + -ary; supplement from Latin supplementum “that which fills up”','The instructor posted supplementary readings for students who wanted more examples.','教師為想看更多例子的學生發布了補充閱讀資料。','education','Adjective: supplementary material is provided in addition to what is already there.','It describes optional or additional resources that extend the main set.',M('The supplementary reading replaced the course book and was the only assigned material.','The supplementary reading was added to the course book as extra material.','Supplementary means provided in addition, not necessarily replacing the main item.'),[Q("supplementary.q1","supplementary.s1","meaning","What are supplementary readings?","Extra readings provided in addition to the main material.","The only assigned text that replaces all other material.","A late evening meal.","Supplementary means provided in addition to what is already there."),Q("supplementary.q2","supplementary.s1","context","Which file is supplementary?","An optional guide added to the required handbook.","The required handbook itself.","A file that deletes the handbook.","The optional guide supplements material that already exists."),Q("supplementary.q3","supplementary.s1","word-choice","Choose the natural phrase.","supplementary information","supplementary to informationly","information supplementarying","The adjective supplementary modifies a noun such as information."),Q("supplementary.q4","supplementary.s1","distinction","Does supplementary information usually replace the main report?","No; it is supplied in addition to the report.","Yes; it always removes the report.","It means the report was written underwater.","The word marks added material rather than replacement.")]);
P('supplementation','Formed from supplement + -ation; supplement is from Latin supplementum “that which fills up.”','supplement + -ation; supplement from Latin supplementum','The nutrition plan includes iron supplementation after a blood test confirmed a deficiency.','血液檢查確認缺鐵後，營養計畫加入了鐵質補充。','nutrition','Noun: supplementation is the act of adding a supplement, especially a nutrient.','The context names a planned addition to food intake based on measured need.',M('The clinician prescribed supplementation by removing iron from the patient’s diet.','The clinician prescribed iron supplementation by adding iron to the patient’s intake.','Supplementation means adding a supplement, not removing the nutrient.'),[Q("supplementation.q1","supplementation.s1","meaning","What is iron supplementation?","The act of adding iron as a nutrient supplement.","Removing iron from every meal.","A process for replacing a doctor.","Supplementation is the act of adding a supplement, especially a nutrient."),Q("supplementation.q2","supplementation.s1","context","When might a clinician recommend supplementation?","When a measured deficiency calls for an added nutrient.","When a patient already has enough and needs no addition.","When replacing food with a title page.","The example shows a nutrient added in response to a confirmed deficiency."),Q("supplementation.q3","supplementation.s1","distinction","How does supplementation differ from a normal meal?","It adds a specific supplement in addition to ordinary intake.","It means no nutrients are consumed.","It is always a late-night dinner.","The word concerns adding a supplement, commonly a nutrient."),Q("supplementation.q4","supplementation.s1","word-choice","Which phrase is natural?","vitamin supplementation","supplementationly vitamins","to supplementation the meal","Supplementation is a noun naming the act of adding nutrients.")]);
P('supplied','Past participle/adjective of supply, from Old French supplier, from Latin supplere “fill up, complete.”','past participle of supply; Latin supplere “complete, fill up”','Each field kit was supplied with a map, a compass, and spare batteries.','每套野外工具都配有地圖、指南針和備用電池。','outdoors','Adjective: supplied with something means provided with an item one needs.','The sentence uses the provided-with construction to list the equipment in each kit.',M('The kit was supplied with no map, no compass, and no batteries, so it contained all required equipment.','The kit was not supplied with a map, compass, or batteries, so it lacked required equipment.','Supplied with means provided with; an empty kit is not supplied with those items.'),[Q("supplied.q1","supplied.s1","meaning","A field kit supplied with a compass has what?","A compass has been provided in the kit.","The compass has been taken away.","The kit is a person who gives lessons.","Supplied with means provided with something needed."),Q("supplied.q2","supplied.s1","context","Which statement uses “supplied” correctly?","The clinic was supplied with clean water each morning.","The clinic supplied with clean water each morning.","The clinic was supply a clean water.","The passive form “was supplied with” means the clinic received water."),Q("supplied.q3","supplied.s1","grammar","Choose the correct completion: “The rooms were ___ fresh towels.”","supplied with","supplied to","supply by","The standard pattern is be supplied with an item."),Q("supplied.q4","supplied.s1","distinction","What does “The village was supplied with food” emphasize?","Food was provided to the village.","The village produced no food and received none.","The food was replaced by a new village.","The adjective/participle indicates provision of needed goods.")]);
P('supplier','Formed from supply + -er, the agent suffix; supply comes from Old French supplier, from Latin supplere “complete.”','supply + -er; supply from Latin supplere “complete”','The hospital’s oxygen supplier delivered replacement cylinders before dawn.','醫院的氧氣供應商在黎明前送來了替換鋼瓶。','health care','Noun sense 1: a person or company selling goods/services to businesses; sense 2: any source that provides something needed.','The context uses a commercial company that sells and delivers a product.',M('The supplier refused to provide oxygen but was called the hospital’s oxygen supplier because it supplied nothing.','A company that provides and delivers oxygen is the hospital’s oxygen supplier.','A supplier provides goods or services; refusing to supply the item contradicts the role.'),[Q("supplier.q1","supplier.s1","meaning","What is a business supplier?","A person or company that sells goods or services to other businesses.","A customer who buys one item for personal use.","A worker who only reviews student theses.","The first source sense is a business selling goods or services to shops and firms."),Q("supplier.q2","supplier.s2","context","Which could be a supplier in the broad sense?","A spring that provides water to a village.","A shop sign with no goods behind it.","A person who receives a delivery but gives nothing.","The second sense includes a place or thing that provides what others need."),Q("supplier.q3","supplier.s1","collocation","Which phrase is standard?","a supplier of medical equipment","a supplier at to medical equipment","a medical supplierly equipment","Supplier of goods is the usual construction."),Q("supplier.q4","supplier.s2","distinction","Can a natural source be called a supplier?","Yes, if it provides something people or organisms need.","No; supplier can only mean a company with a cash register.","Yes, but only if it supervises a school.","The broader sense includes a place or thing that provides a needed resource.")]);
P('supply','From Old French supplier “fill up, provide,” from Latin supplere “complete, fill up.” The verb means provide; the noun can mean an available amount.','Old French supplier, from Latin supplere “fill up, complete”','The relief team will supply clean water to the isolated village.','救援隊將向偏遠村莊提供乾淨飲水。','humanitarian aid','Verb sense 1: give someone what they need; noun sense 2: an amount available for use.','The context uses the verb with a recipient marked by to; the entry also includes the noun stock/amount sense.',M('The team supplied the village by taking away its only water source.','The team supplied the village with clean water.','To supply someone is to provide something needed, not remove their source.'),[Q("supply.q1","supply.s1","meaning","What did the relief team do when it supplied the village?","Provided something the residents needed.","Took away their only resource.","Replaced the village with a new road.","Supply as a verb means give someone something they need."),Q("supply.q2","supply.s2","context","A shop has a limited supply of batteries. What does supply mean here?","The amount available to use.","The act of supervising workers.","The person who buys them.","The noun sense is an available amount of something."),Q("supply.q3","supply.s1","grammar","Which construction is correct?","They supplied water to the camp.","They supplied to water the camp.","They supplyed water to the camp.","Supply can take an object followed by to + recipient; the past form is supplied."),Q("supply.q4","supply.s2","distinction","What does “The water supply is running low” refer to?","The available amount of water.","The person delivering the water.","The act of writing a title underneath another.","Supply as a noun can mean the amount available for use.")]);
P('support','From Old French supporter, from Latin supportare “carry, sustain,” from sub- “up from under” + portare “carry.” Meanings include backing, bearing weight, and financial help.','Latin supportare “carry, sustain,” from sub- + portare “carry”','Steel columns support the roof while the crew replaces a damaged beam.','工人更換受損橫樑時，鋼柱支撐著屋頂。','construction','Verb sense 1: agree with or help a person/idea/team; sense 2: hold weight; sense 3: noun for money or help that sustains.','This context uses the physical load-bearing sense; the word also means backing an idea and help that lets someone continue.',M('The weak shelf supports the entire stone statue even though the statue rests on the floor.','The stone base supports the statue by holding its weight.','Support in the physical sense means hold the weight so something does not fall.'),[Q("support.q1","support.s1","meaning","What does it mean to support a candidate?","Back the candidate and help their campaign.","Hold the candidate physically above the ground only.","Replace the candidate’s last name.","Support can mean agree with and help a person or cause."),Q("support.q2","support.s2","context","Which beam supports the roof?","The beam holds the roof’s weight so it does not fall.","The beam announces the roof’s title.","The beam provides a monthly magazine.","The physical sense is to hold an object's weight."),Q("support.q3","support.s3","meaning","A family receives support while a parent is ill. What may support be?","Money or help that lets the family continue.","A roof beam only.","A new rival company.","The noun sense includes money or help given so a person or thing can continue."),Q("support.q4","support.s1","collocation","Which phrase uses the cause/idea sense?","support the proposal","support under the proposal to","support the proposally","Support can take a person, team, or idea as its direct object.")]);
P('supporter','Formed from support + -er, a person who supports; support comes from Latin supportare “carry, sustain.”','support + -er; support from Latin supportare “carry, sustain”','A supporter raised funds for the neighborhood food bank.','一名支持者為社區食物銀行募款。','community','Noun sense 1: a person who publicly backs a cause; sense 2: a fan who follows and cheers for a sports team.','The context uses a cause supporter; sports supporter is another established sense.',M('A supporter opposed the food bank, campaigned against it, and gave no help.','An opponent opposed the food bank, while a supporter backed it and offered help.','A supporter backs a person, idea, or cause; active opposition is the opposite.'),[Q("supporter.q1","supporter.s1","meaning","Who is a supporter of a cause?","A person who publicly backs it.","A person campaigning to end it.","A person who manages the supermarket.","A supporter publicly backs a person, idea, or cause."),Q("supporter.q2","supporter.s2","context","At a football match, who is a supporter?","A fan who follows and cheers for the team.","A referee who records time only.","A player from the opposing team.","The sports sense names a person who follows and cheers for a team."),Q("supporter.q3","supporter.s1","word-choice","Which sentence uses the cause sense?","Supporters collected signatures for the library.","The supporter scored the winning goal on the field.","The supportingly library closed early.","Collecting signatures publicly backs the library cause."),Q("supporter.q4","supporter.s2","distinction","What distinguishes a team supporter from a team player?","The supporter cheers for the team but need not play on it.","The supporter is always the referee.","The supporter has to own the stadium.","A supporter follows and cheers for a team; a player competes in it.")]);
P('supporting','Formed from support + -ing; support comes from Latin supportare “carry, sustain.” It describes helpful evidence, physical support, or a secondary acting role.','support + -ing; support from Latin supportare “sustain”','The witness provided supporting evidence for the timeline in the investigation.','證人提供了支持調查時間線的證據。','law','Adjective sense 1: providing help, backing, or evidence; sense 2: a smaller role that helps a lead actor.','The context uses evidence that backs a claim; supporting actor is a distinct film/theater use.',M('The supporting evidence contradicted every part of the timeline and gave it no backing.','The contrary evidence contradicted the timeline; supporting evidence would back it up.','Supporting evidence provides help or backing rather than contradicting the claim.'),[Q("supporting.q1","supporting.s1","meaning","What does supporting evidence do?","It backs up a person’s claim or account.","It proves the claim is unrelated to the facts.","It replaces the investigator.","Supporting evidence provides backing for a claim."),Q("supporting.q2","supporting.s2","context","Who has a supporting role in a film?","An actor with a smaller part that helps the lead story.","The lead actor in the central role only.","A person who supplies electricity to the set.","The source’s second sense is a smaller part helping the leading actor."),Q("supporting.q3","supporting.s1","word-choice","Which phrase is natural?","supporting documentation","supporting to documentation","documentation supportinglyly","Supporting modifies documentation to say it backs up a claim."),Q("supporting.q4","supporting.s1","distinction","How is supporting evidence different from contrary evidence?","It strengthens or backs the account instead of opposing it.","It is always shown by a supporting actor.","It means evidence stored under a floor.","The adjective means providing help, backing, or evidence.")]);
P('supportive','Formed from support + -ive; support comes from Latin supportare “sustain.” It can describe helpful care or practical backing such as funding or evidence.','support + -ive; support from Latin supportare “sustain”','Her colleagues were supportive when she returned to work after surgery.','她手術後重返工作時，同事們給予了她支持。','workplace','Adjective sense 1: kind and helpful in difficulty; sense 2: providing practical backing such as money or evidence.','This context uses emotional and interpersonal help; the source also includes financial or evidential support.',M('Her colleagues were supportive by mocking her recovery and refusing any help.','Her colleagues were unsupportive because they mocked her recovery and refused help.','Supportive behavior is kind and helpful, not mocking or refusing assistance.'),[Q("supportive.q1","supportive.s1","meaning","What does a supportive friend do?","Offers kind help during a difficult time.","Mocks the person and refuses assistance.","Replaces their old apartment.","Supportive means kind and helpful when someone is in difficulty."),Q("supportive.q2","supportive.s2","context","Which document is supportive of a funding request?","A budget and evidence that back the request.","A document that contradicts every cost estimate.","A dinner invitation unrelated to the project.","Supportive can mean providing practical or evidential backing."),Q("supportive.q3","supportive.s1","collocation","Which phrase is standard?","a supportive colleague","a supportive for colleague","supportive colleaguely","The adjective directly modifies colleague."),Q("supportive.q4","supportive.s2","distinction","Can a supportive policy provide more than emotional kindness?","Yes; it can provide money or other practical backing.","No; it can only describe a smile.","Yes, but only by replacing a supervisor.","The second source sense includes financial or practical support.")]);
P('suppose','From Old French supposer, from Latin supponere “put under, assume,” from sub- “under” + ponere “put.” Senses include think something may be true, accept an assumption, or be expected to do something.','Old French supposer, from Latin supponere “put under, assume”','I suppose the train is delayed because the station board has changed its time.','我想火車可能誤點了，因為車站看板更新了時間。','conversation','Verb sense 1: think something is true but remain unsure; sense 2: assume for discussion; sense 3: be expected or required (be supposed to).','The example expresses a tentative belief; the entry also includes hypothetical assumptions and expectations.',M('I suppose the train is delayed, and I know this with absolute certainty.','I am certain the train is delayed; “I suppose” would signal less certainty.','Suppose normally marks a belief or assumption rather than absolute certainty.'),[Q("suppose.q1","suppose.s1","meaning","What does “I suppose the shop is closed” suggest?","I think it is closed, but I am not completely sure.","I have proved beyond doubt that it is open.","I am required to close it.","Suppose can express a belief held with some uncertainty."),Q("suppose.q2","suppose.s2","context","In “Suppose the map is wrong; what route could we take?”, what does suppose do?","It asks us to accept a possibility for discussion.","It orders someone to buy a map.","It confirms that the map is certainly correct.","The hypothetical sense accepts something as true for the sake of discussion."),Q("suppose.q3","suppose.s3","grammar","What does “You are supposed to wear a helmet” mean?","You are expected or required to wear one.","You may wear one only if you want.","Someone thinks you already wore it, without expectation.","Be supposed to expresses an expectation or requirement."),Q("suppose.q4","suppose.s1","distinction","Why is “I suppose” softer than “I know”?","It marks a thought or assumption rather than certainty.","It means the speaker is giving an order.","It names a person’s supervisor.","Suppose can indicate uncertainty, unlike the stronger claim in “I know.”")]);
P('supposed','Past participle/adjective of suppose, from Old French supposer and Latin supponere “assume.” It can mark a doubtful claim or an expectation.','past participle of suppose; Latin supponere “assume”','The supposed cure had never been tested in a controlled clinical trial.','這種所謂的療法從未經過對照臨床試驗。','medicine','Adjective sense 1: alleged or claimed, often with doubt; sense 2: expected or believed to do something.','The example uses a skeptical “so-called” meaning; be supposed to expresses expectation.',M('The supposed cure was clinically proven and had no doubtful claims, yet the report called it supposed to express certainty.','The alleged cure was called “supposed” because its claims had not been clinically tested.','Supposed in the doubtful sense signals a claim is alleged rather than established.'),[Q("supposed.q1","supposed.s1","meaning","A supposed cure has not been tested. What does “supposed” signal?","People claim it is a cure, but the claim is doubtful.","It is guaranteed to cure every illness.","It is required to treat the doctor.","Supposed can express skepticism about something people claim is true."),Q("supposed.q2","supposed.s2","context","What does “the files are supposed to be here” mean?","They are expected or believed to be here.","The files are alleged to be a fake medicine.","The files have been destroyed with certainty.","The second sense is expected or believed to be in a particular place."),Q("supposed.q3","supposed.s1","distinction","Why might a writer say “the supposed expert”?","The writer doubts that the person really deserves the title.","The writer confirms a formal job requirement.","The person is a substitute for a building.","Supposed can distance the writer from a disputed claim."),Q("supposed.q4","supposed.s2","grammar","Which sentence uses “be supposed to” for an expectation?","The package is supposed to arrive today.","The supposed package was a rumor.","They supposed the package on the table.","Be supposed to states what is expected to happen.")]);
P('supposedly','Formed from supposed + -ly; supposed is the past participle of suppose, from Latin supponere “assume.”','supposed + -ly; suppose from Latin supponere “assume”','The supposedly secure archive was accessed by an unauthorized account.','據稱安全的檔案庫遭到未授權帳戶登入。','cybersecurity','Adverb: supposedly reports what people say or believe, while leaving open that it may not be true.','The context distances the speaker from the claim that the archive was secure.',M('The supposedly secure archive was verified as secure beyond all doubt, and the writer used supposedly to state certainty.','The supposedly secure archive was claimed to be secure, but the breach cast doubt on that claim.','Supposedly marks a reported or believed claim that may not be true; it does not itself guarantee certainty.'),[Q("supposedly.q1","supposedly.s1","meaning","What does “supposedly secure” suggest after a data breach?","People claimed it was secure, but that claim may be false.","It has been proven perfectly secure.","It was designed to be a supermarket.","Supposedly reports a belief or claim while leaving doubt."),Q("supposedly.q2","supposedly.s1","context","Which sentence uses “supposedly” naturally?","The supposedly empty room still contained several boxes.","The room supposedly empty was definitely filled by a ghost in every case.","She supposedly the boxes yesterday.","The adverb signals a claim that the observed facts may contradict."),Q("supposedly.q3","supposedly.s1","distinction","Does “supposedly” always mean the speaker accepts the claim?","No; it can signal doubt about what people say or believe.","Yes; it guarantees the claim is true.","No; it only describes a room’s surface.","The word can distance the speaker from an unverified claim."),Q("supposedly.q4","supposedly.s1","word-choice","Which word best fits a reported but uncertain claim?","supposedly","certainly","physically","Supposedly means as people say or believe, though it may not be true.")]);
P('supposition','From Latin suppositionem, from supponere “put under, assume,” from sub- + ponere “put.” It can be an unproved assumption or a premise for an argument.','Latin suppositionem, from supponere “assume, put under”','The report’s conclusion rested on the supposition that every sample had been stored correctly.','報告的結論建立在所有樣本都妥善儲存這項假定上。','research','Noun sense 1: an assumption without proof; sense 2: a starting premise for an argument or theory.','The context states an unverified assumption on which the conclusion depends.',M('The supposition was proved by complete laboratory records, so it was no longer an assumption.','The supposition remained unproved because the laboratory records were incomplete.','A supposition is an assumption made without proof; complete evidence would substantiate it.'),[Q("supposition.q1","supposition.s1","meaning","What is a supposition?","An assumption made without proof.","A result directly measured beyond doubt.","A person who repairs an archive.","The first sense is an assumption that something is true without proof."),Q("supposition.q2","supposition.s2","context","In a theory, what is a starting supposition?","An idea accepted as the premise for the argument.","The final answer after all evidence is collected.","A random decorative sentence.","The second sense is a starting point accepted for an argument or theory."),Q("supposition.q3","supposition.s1","distinction","Why should a report label an untested cause a supposition?","It signals the cause is assumed rather than proven.","It proves the cause experimentally.","It names a supporting employee.","A supposition is an assumption without proof."),Q("supposition.q4","supposition.s2","word-choice","Which phrase uses the premise sense?","The argument begins with the supposition that resources are limited.","The supposition was a late evening meal.","She suppositioned the report.","The phrase marks an idea taken as the starting point for reasoning.")]);
P('suppress','From Latin supprimere “press down, keep back,” from sub- “down” + premere “press.” It means stop activity by force, restrain a feeling, or prevent information from appearing.','Latin supprimere “press down, keep back,” from sub- + premere “press”','The authorities tried to suppress the protest by closing the square and arresting organizers.','當局試圖封閉廣場並逮捕組織者，以鎮壓抗議活動。','politics','Verb sense 1: stop activity by force; sense 2: restrain one’s feelings; sense 3: prevent information from being published.','The example uses force against public activity; the entry also includes emotional restraint and concealment of information.',M('The government suppressed the protest by publicly encouraging every demonstration to continue.','The government supported the protest by publicly encouraging every demonstration to continue.','Suppress means stop activity by force, while encouraging it to continue is support.'),[Q("suppress.q1","suppress.s1","meaning","What does it mean to suppress a protest?","Stop it by force or authority.","Invite it to grow without restriction.","Publish a magazine supplement.","The first source sense is stopping an activity by force."),Q("suppress.q2","suppress.s2","context","If someone suppresses a laugh during a ceremony, what do they do?","Try not to show the feeling or reaction.","Publish the laugh in a newspaper.","Force a crowd to leave a square.","The emotional sense means stop yourself from showing a feeling."),Q("suppress.q3","suppress.s3","meaning","What does a company do if it suppresses a safety report?","Prevents the information from being published or disclosed.","Makes the report easier to find.","Adds the report as a supplement.","The information sense is to prevent publication."),Q("suppress.q4","suppress.s1","distinction","Which action is suppression of public activity?","Using force to stop a demonstration.","Allowing people to assemble peacefully.","Adding evidence to a public report.","The first sense describes force used to stop an activity.")]);
P('suppression','From Latin suppressionem, noun of action from supprimere “press down, restrain.”','Latin suppressionem, from supprimere “press down, restrain”','The report documented the suppression of peaceful demonstrations.','報告記錄了對和平示威活動的鎮壓。','politics','Noun sense 1: force used to stop resistance or protest; sense 2: deliberately stopping a feeling, thought, or process.','The context uses political force; suppression can also be internal restraint of feelings or processes.',M('The suppression of the protest meant the authorities protected the demonstrators and let the rally proceed.','The protection of the protest meant the authorities let the rally proceed; suppression would have stopped it.','Suppression is the use of force to stop resistance or protest, the opposite of allowing it to proceed.'),[Q("suppression.q1","suppression.s1","meaning","What does suppression of a protest involve?","Using force to stop people from resisting or demonstrating.","Providing a stage for the protest to continue.","Writing a thesis subtitle.","The political sense is force used to stop resistance or protest."),Q("suppression.q2","suppression.s2","context","In psychology, what might suppression of a feeling mean?","Deliberately stopping the feeling from being shown.","Paying a fee to express it.","A crowd moving suddenly forward.","The second sense is deliberately stopping a feeling or thought from showing."),Q("suppression.q3","suppression.s1","distinction","Which phrase signals political suppression?","the suppression of peaceful opposition","the growth of open public debate","the regular supply of food","The phrase names force used to stop people resisting or protesting."),Q("suppression.q4","suppression.s2","word-choice","Which use refers to an internal process?","suppression of anger","suppression of a public march by police","suppression of a rebel uprising","The anger example refers to deliberately restraining a feeling.")]);
P('supremacy','Formed from supreme + -acy; supreme comes from Latin supremus, superlative of superus “above.”','supreme + -acy; supreme from Latin supremus “highest”','The treaty rejected any nation’s claim to military supremacy over its neighbors.','條約拒絕任何國家宣稱對鄰國擁有軍事優勢地位。','politics','Noun: supremacy is the position of being most powerful or the highest authority.','The context names a dominant political or military position, not a feeling of personal pride alone.',M('The treaty established the small state’s supremacy by making it the least powerful and subordinate nation.','The treaty denied the small state’s supremacy by making it the least powerful and subordinate nation.','Supremacy means the position of greatest power or authority, not the least powerful status.'),[Q("supremacy.q1","supremacy.s1","meaning","What is military supremacy?","The position of being the most powerful military authority.","A feeling that one has no authority.","A late meal after work.","Supremacy is a position of greatest power or authority."),Q("supremacy.q2","supremacy.s1","context","Which event could change a nation’s supremacy?","A shift that leaves another nation with greater power.","A new school calendar is printed.","A company supplies office paper.","Supremacy concerns which side holds the highest power or authority."),Q("supremacy.q3","supremacy.s1","distinction","How does supremacy differ from superiority in one product test?","Supremacy is a position of greatest power or authority, often broader than a single comparison.","Supremacy means a small scratch on a surface.","The words mean a late-night meal.","The noun denotes the position of most power or highest authority."),Q("supremacy.q4","supremacy.s1","collocation","Which phrase is natural?","naval supremacy","naval supremacy to in yesterday","supremacyly naval","Supremacy commonly names a field of dominance, as in naval supremacy.")]);
P('supreme','From Latin supremus “highest,” superlative of superus “above.” It can mean highest in authority or extremely important/great.','Latin supremus “highest,” superlative of superus “above”','The supreme court issued a ruling that applies nationwide.','最高法院作出了一項適用於全國的裁決。','law','Adjective sense 1: highest in rank, power, or authority; sense 2: very great or more important than anything else.','The context uses the highest-authority sense; the adjective can also intensify importance or degree.',M('The supreme court was the lowest local court with no authority over any ruling.','The supreme court was the highest court with final authority over the ruling.','Supreme means highest in rank or authority, not the lowest court.'),[Q("supreme.q1","supreme.s1","meaning","What does “supreme authority” mean?","The highest rank or power.","The least important position.","A person who sells food at a market.","Supreme means highest in rank, power, or authority."),Q("supreme.q2","supreme.s2","context","Which achievement might be called a supreme effort?","An exceptionally great effort on which everything depended.","An ordinary small task completed casually.","A task performed below a bridge.","The second sense means very great or more important than anything else."),Q("supreme.q3","supreme.s1","word-choice","Which title uses the authority sense?","the supreme commander","a supremely flexible dancer","a supreme flavor of soup","Commander identifies rank and authority."),Q("supreme.q4","supreme.s2","distinction","If a concern is of supreme importance, how important is it?","Extremely important, above other concerns.","A minor detail that can be ignored.","A fact only about the outside surface.","The second sense indicates very great or overriding importance.")]);
P('supremely','Formed from supreme + -ly; supreme is from Latin supremus “highest.”','supreme + -ly; from Latin supremus “highest”','The new lens is supremely effective in low light, capturing details the older model missed.','新鏡頭在低光環境下極為有效，能捕捉舊款錯過的細節。','photography','Adverb: supremely means to the highest or an extreme degree.','The word intensifies how effective the lens is; it does not mean “in a superior position.”',M('The lens was supremely ineffective and performed at an extreme degree of effectiveness.','The lens was supremely effective and performed at an extreme degree of effectiveness.','“Ineffective” contradicts the description of an extreme degree of effectiveness.'),[Q("supremely.q1","supremely.s1","meaning","What does “supremely effective” mean?","Effective to an extreme degree.","Slightly effective only in daylight.","Located physically above the camera.","Supremely means in the highest or an extreme degree."),Q("supremely.q2","supremely.s1","context","Which sentence uses “supremely” naturally?","The mountain route is supremely difficult in winter.","The route supremely a bridge yesterday.","She bought a supremely at the market.","The adverb modifies the adjective difficult to mean extremely difficult."),Q("supremely.q3","supremely.s1","distinction","Does “supremely skilled” mean a person is physically higher than others?","No; it means skilled to an exceptional degree.","Yes; the person must stand on a roof.","No; it means the person is a late meal.","Supremely is a degree adverb, not a physical-location term."),Q("supremely.q4","supremely.s1","word-choice","Which phrase is closest in meaning to “supremely important”?","extremely important","slightly important","not important at all","The adverb marks the highest or an extreme degree.")]);
P('surcharge','Formed from French surcharger, from sur- “over” + charger “load.” It is an extra charge or the act of adding one.','French surcharger “overcharge,” from sur- + charger “load”','The hotel added a surcharge for parking, which was not included in the room price.','飯店另收停車附加費，該費用未包含在房價內。','travel','Noun sense 1: an extra amount paid in addition to the usual price; verb sense 2: charge someone that extra amount.','The context uses the added fee noun; the word can also function as a verb meaning to impose it.',M('The hotel surcharge reduced the bill by removing every additional fee.','The hotel surcharge increased the bill by adding an extra fee.','A surcharge is an additional amount payable on top of the normal price.'),[Q("surcharge.q1","surcharge.s1","meaning","What is a parking surcharge?","An extra fee added to the usual price.","A discount that removes the base price.","A parking supervisor.","A surcharge is an extra amount that must be paid in addition to the usual price."),Q("surcharge.q2","surcharge.s2","context","What does a hotel do when it surcharges a card payment?","Charges an additional amount beyond the normal price.","Refunds the full room cost.","Adds a subtitle to the booking.","As a verb, surcharge means charge someone an extra amount."),Q("surcharge.q3","surcharge.s1","distinction","If a ticket lists a $4 surcharge, how should a buyer treat it?","As an extra amount on top of the listed base price.","As a guaranteed refund.","As a replacement ticket.","The noun names an additional amount payable beyond the usual cost."),Q("surcharge.q4","surcharge.s2","grammar","Which sentence uses “surcharge” as a verb?","The carrier may surcharge oversized luggage.","The surcharge appeared on the receipt.","An extra surcharge was listed.","Surcharge is the action verb in the first sentence; it means impose an added fee.")]);
P('surd','From Latin surdus “deaf, dull-sounding.” In mathematics it names an irrational root; in phonetics it can mean an unvoiced consonant.','Latin surdus “deaf, dull-sounding”','In algebra, √2 is a surd because it cannot be expressed as a ratio of whole numbers.','在代數中，√2 是一個無理根，因為它無法表示為整數之比。','mathematics','Noun sense 1: a number/root not expressible as a simple fraction; sense 2: an unvoiced consonant sound.','The context uses the mathematical sense; phonetics uses the same term for a sound made without vocal-cord vibration.',M('The rational number 3/4 is a surd because it is written as a fraction of whole numbers.','The irrational root √2 is a surd because it cannot be written as a ratio of whole numbers.','A surd in mathematics cannot be expressed as a simple fraction; 3/4 is rational.'),[Q("surd.q1","surd.s1","meaning","Which number is a mathematical surd?","√2","3/4","12","A surd is a root that cannot be written as a simple fraction of whole numbers."),Q("surd.q2","surd.s2","context","In phonetics, what is a surd consonant?","A consonant produced without vocal-cord vibration.","A vowel sung loudly.","A written fraction with a square root.","The phonetic sense is an unvoiced consonant sound."),Q("surd.q3","surd.s1","distinction","Why is 3/4 not a surd in the mathematical sense?","It is already a ratio of whole numbers.","It has no numerator.","It is a consonant sound.","The definition excludes numbers expressible as simple fractions."),Q("surd.q4","surd.s2","word-choice","Which description fits a phonetic surd?","An unvoiced sound such as /s/.","A sound made with strong vocal-cord vibration only.","A number equal to twelve.","A surd consonant is produced without the vocal cords vibrating.")]);
P('sure','From Old French seur, from Latin securus “free from care, secure.” It means confident, certain/reliable, or a conversational “yes.”','Old French seur, from Latin securus “secure, free from care”','I am sure the package was delivered because the tracking page shows a signature.','我確信包裹已送達，因為追蹤頁面顯示有人簽收。','conversation','Adjective sense 1: confident that something is true; sense 2: certain to happen or reliable; sense 3: informal response meaning yes/certainly.','The context uses confidence based on evidence; sure can also describe reliable outcomes or give an affirmative reply.',M('I am sure the parcel arrived, although I have no evidence and strongly doubt that it did.','I am unsure whether the parcel arrived because I have no evidence.','Sure expresses confidence; strong doubt and no evidence call for unsure.'),[Q("sure.q1","sure.s1","meaning","What does “I am sure the parcel arrived” express?","Confidence that the claim is true.","A belief that it definitely did not arrive.","A request for a late meal.","The first sense is confidence that something is true."),Q("sure.q2","sure.s2","context","If a bridge is a sure route in bad weather, what does sure mean?","Reliable or certain to work.","A person who manages a school.","A route that exists only in a dream.","Sure can mean certain to happen or able to be trusted."),Q("sure.q3","sure.s3","usage","A friend asks, “Can you help me move?” You answer “Sure.” What do you mean?","Yes, certainly.","I am unsure and refuse.","The move is a physical surface.","In informal conversation, sure can mean yes or certainly."),Q("sure.q4","sure.s1","distinction","Which phrase correctly asks about confidence?","Are you sure the door is locked?","Are you surely the door is locked?","Do you sure about the locked door?","The adjective sure can follow be and express confidence in a claim.")]);
P('surely','Formed from sure + -ly; sure comes from Latin securus “secure.”','sure + -ly; sure from Latin securus “secure”','Surely the lab will repeat the measurement before publishing the result.','實驗室肯定會在發布結果前重做測量吧。','conversation','Adverb sense 1: emphatically express certainty; sense 2: infer that something must happen or be true.','Here the speaker strongly expects a careful lab to repeat the measurement.',M('Surely the lab will repeat the measurement, but the speaker means there is no reason to expect it.','The lab will surely repeat the measurement because it must check the result.','Surely normally emphasizes certainty or an inference, not a lack of expectation.'),[Q("surely.q1","surely.s1","meaning","What does “Surely the lab checked the result” express?","The speaker emphasizes confidence that it did.","The speaker says the lab definitely did not check.","The speaker asks about a late meal.","The first sense uses surely to emphasize certainty."),Q("surely.q2","surely.s2","context","“Surely the lights will come on when power returns.” What does this imply?","They must come on if power is restored.","They are forbidden to come on.","The speaker has no prediction at all.","The second sense says something must happen or be true."),Q("surely.q3","surely.s1","distinction","Which word can replace surely in “Surely you remember the agreement”?","Certainly","Never","Subsequently","Here surely emphasizes the speaker’s confidence."),Q("surely.q4","surely.s2","word-choice","Which inference fits “Surely the train will stop at the final station”?","It must stop there as expected.","It is impossible that it will stop.","It has already been replaced by a newer rule.","Surely can express that something must happen or be true.")]);
P('surely not','A conversational phrase formed from surely + not; surely is sure + -ly and signals an expectation or emphatic belief.','surely + not; surely from sure + -ly','“Surely not,” Lina said when told the museum had closed permanently.','聽說博物館永久關閉時，莉娜說：「不會吧。」','conversation','Fixed response: surely not expresses disbelief, surprise, or rejection of a claim.','The phrase responds to news the speaker finds hard to believe.',M('When told her flight was canceled, Lina said “Surely not” to mean she completely expected and welcomed the cancellation.','When told her flight was canceled, Lina said “Surely not” to show surprise and disbelief.','Surely not expresses that the speaker does not believe or is surprised by the claim.'),[Q("surely not.q1","surely not.s1","meaning","Someone says, “The concert is canceled.” You reply, “Surely not!” What do you express?","Disbelief or surprise.","A calm confirmation that you already knew.","A request to pay an extra fee.","The phrase says you do not believe the news or are very surprised."),Q("surely not.q2","surely not.s1","context","Which reply fits the phrase “Surely not”?","“They lost the only key?” “Surely not!”","“Would you like tea?” “Surely not means yes, please.”","“What time is it?” “Surely not is a number.”","It is a response to an unexpected or hard-to-believe statement."),Q("surely not.q3","surely not.s1","distinction","Is “Surely not” usually enthusiastic agreement?","No; it expresses disbelief or strong surprise.","Yes; it always means certainly yes.","No; it means a supervisor arrived.","The phrase signals that the speaker doubts or is surprised by the claim."),Q("surely not.q4","surely not.s1","word-choice","Which phrase has the same reaction?","That can’t be right!","I knew that would happen.","The price includes the fee.","A surprised rejection matches surely not.")]);
P('surf','The noun names breaking shore waves; the verb “surf” is a shortened form associated with surfboard/surf-boarding and riding waves. Internet surf later extended the verb.','surf is related to surface; the wave noun and surfing verb developed as related coastal terms','The children watched white surf break against the rocks below the lighthouse.','孩子們看著燈塔下白色浪花拍打岩石。','coast','Noun sense 1: breaking waves near shore; verb sense 2: ride waves on a board; sense 3: browse internet information or channels.','The context uses the shore-wave noun; the verb has sports and internet-browsing senses.',M('The surf was a flat dry beach with no breaking waves.','The surf was the breaking waves near the shore.','Surf as a noun is the waves that break near shore, not the dry beach.'),[Q("surf.q1","surf.s1","meaning","What is surf along a rocky coast?","White waves breaking near the shore.","Dry sand far inland.","A doctor’s surgery room.","The noun sense is the white waves that break near shore."),Q("surf.q2","surf.s2","context","What does a surfer do?","Rides waves while standing or balancing on a board.","Reads a website without an internet connection.","Builds an underground train.","The sports verb sense is to ride on waves standing on a board."),Q("surf.q3","surf.s3","meaning","What does “surf the web” mean?","Look quickly through information online.","Ride a physical wave on a board indoors.","Repair the surface of a road.","The internet sense means browse information or channels."),Q("surf.q4","surf.s1","distinction","Which observation describes surf as a noun?","Foam-topped waves roll onto the beach.","A student opens several news websites.","A board rider glides across a wave.","The first is the shore-wave noun; the other choices use the verb senses.")]);
P('surface','From Old French surface, from sur- “over” + face, ultimately Latin facies “face.” It can mean an outer layer, outward appearance, or rise/appear.','Old French surface, from sur- “over” + face','Oil floated in a thin layer on the surface of the water.','油浮在水面上形成薄薄的一層。','science','Noun sense 1: outside/top part; noun sense 2: outward appearance; verb sense 3: come to the top of water or appear after being hidden.','The context uses the physical top layer; figuratively the surface can conceal deeper facts.',M('The oil sank to the surface of the lake and disappeared beneath the water.','The oil sank below the surface of the lake.','The surface is the top or outside; something below it has not reached the surface.'),[Q("surface.q1","surface.s1","meaning","What is the surface of a table?","Its outer or top part.","The table’s hidden history only.","The room under the table.","Surface means the outside or top part of something."),Q("surface.q2","surface.s2","context","What does “calm on the surface” mean figuratively?","It appears calm, though deeper feelings may differ.","It is physically underwater.","It has no outside at all.","The figurative sense concerns what seems true without looking deeper."),Q("surface.q3","surface.s3","grammar","Which sentence uses surface as a verb?","The diver surfaced after several minutes.","The surface was rough.","The paint covered the surface.","Surfaced is a verb meaning came up to the top of the water."),Q("surface.q4","surface.s3","distinction","If a hidden problem surfaces, what happens?","It appears after being concealed.","It becomes the table’s outside layer.","It is permanently buried again.","The verb also means appear after having been hidden.")]);
P('surge','From Latin surgere “rise, get up.” As a noun it is a sudden large increase; as a verb it can describe forceful forward movement.','Latin surgere “rise, get up”','A surge in electricity demand pushed the grid close to capacity during the heat wave.','熱浪期間，電力需求激增，使電網接近負載上限。','energy','Noun sense 1: a sudden large increase; verb sense 2: move forward suddenly and with force.','The context uses the measurable increase sense; crowds or water can also surge forward forcefully.',M('There was a surge in demand when demand suddenly fell to zero.','There was a drop in demand when demand suddenly fell to zero.','A surge is a sudden large increase, not a fall.'),[Q("surge.q1","surge.s1","meaning","What is a surge in electricity demand?","A sudden large increase in demand.","A steady decrease to nothing.","A late evening meal.","The first sense is a sudden large increase."),Q("surge.q2","surge.s2","context","What happens when a crowd surges toward an exit?","It moves forward suddenly and forcefully.","It remains perfectly still.","It is measured as a decimal root.","The verb sense describes sudden forceful movement."),Q("surge.q3","surge.s1","distinction","Which statistic reports a surge in visitors?","A sharp jump from 200 visitors to 900 in one hour.","A decline from 900 visitors to 200.","Exactly 200 visitors each hour for a year.","The noun sense is a sudden large increase."),Q("surge.q4","surge.s2","word-choice","Choose the sentence using the movement sense.","Waves surged over the seawall during the storm.","A surge in prices worried shoppers.","The clinic scheduled surgery for Tuesday.","Waves moving forcefully over the wall use the verb sense.")]);
P('surgeon','From Anglo-French surgien, from Latin chirurgia and Greek kheirourgos “working with the hand.” A surgeon is a doctor who operates; regional titles include military or ship doctors.','Anglo-French surgien, from Latin chirurgia, Greek kheirourgos “working with the hand”','The surgeon explained the risks before operating on the patient’s knee.','外科醫生在為病人的膝蓋動手術前說明了風險。','medicine','Noun sense 1: a doctor who treats illness by operating; sense 2: a military or ship doctor who treats wounds.','The context uses the general medical specialist; the source also records military and ship roles.',M('The surgeon treated the knee by refusing to perform or advise on any operation.','The surgeon treated the knee by performing an operation or planning surgical care.','A surgeon is a doctor who treats illness by operating, not by refusing surgical care.'),[Q("surgeon.q1","surgeon.s1","meaning","What does a surgeon specialize in?","Treating illness or injury through operations.","Selling groceries in a self-service store.","Managing an apartment building.","The general sense is a doctor who cuts open the body to treat illness."),Q("surgeon.q2","surgeon.s2","context","Who might be called a ship surgeon?","A doctor aboard a ship who treats wounds or illness.","The ship’s navigator with no medical role.","A passenger who reads the map.","The source includes a ship doctor as a specialized sense."),Q("surgeon.q3","surgeon.s1","distinction","Which patient is most likely to consult a surgeon?","Someone needing an operation to repair a damaged joint.","Someone asking where the supermarket is.","Someone with a routine question about a book title.","Surgeons are doctors who treat by operating."),Q("surgeon.q4","surgeon.s2","meaning","What does “regimental surgeon” refer to?","A military doctor who treats service members.","A civilian who sells medical textbooks.","A person who conducts a survey.","The second source sense includes a military doctor treating wounds.")]);
P('surgery','From Latin chirurgia, from Greek kheirourgia “work of the hand,” from kheir “hand” + ergon “work.” It can mean an operation or a doctor’s practice/clinic.','Latin chirurgia, from Greek kheirourgia “work of the hand”','She will have surgery on her shoulder next week.','她下週將接受肩部手術。','medicine','Noun sense 1: medical treatment involving an operation; sense 2: a place where a doctor sees patients or its consulting hours.','The example uses the operation sense; British usage also uses surgery for a clinic or appointment hours.',M('The patient had surgery by attending a routine appointment with no operation or procedure.','The patient visited the doctor’s surgery for a routine appointment but did not have an operation.','Surgery can mean a clinic, but “have surgery” generally means undergo an operation.'),[Q("surgery.q1","surgery.s1","meaning","What does “have surgery on a shoulder” mean?","Undergo an operation on the shoulder.","Visit a supermarket to buy a shoulder of meat.","Become a doctor without training.","The first sense is medical treatment in which a doctor operates."),Q("surgery.q2","surgery.s2","context","A British patient says, “I have an appointment at the surgery.” Where are they going?","To the doctor’s clinic.","To an operating theater for certain.","To a surf beach.","The second sense can mean the place where a doctor sees patients."),Q("surgery.q3","surgery.s1","distinction","How is “surgery” used in “the surgeon performed surgery”?","It names an operation or operative treatment.","It names the clinic building only.","It names an extra fee.","The verb performed points to the operation sense."),Q("surgery.q4","surgery.s2","usage","Which sentence uses the clinic sense?","The doctor’s surgery is open from nine until noon.","She had surgery to repair the fracture.","The surgeon scheduled surgery tomorrow.","The clinic being open during hours uses surgery for the place/practice.")]);
P('surging','Formed from surge + -ing; surge comes from Latin surgere “rise.”','surge + -ing; surge from Latin surgere “rise”','Surging river water spilled over the bank after two days of heavy rain.','連續兩天大雨後，奔湧的河水漫過了河岸。','weather','Adjective: surging water, crowds, or numbers are rising or rushing forcefully.','The example uses forceful water movement; the word can describe increasing numbers as well.',M('The surging river stayed perfectly still at the same level all day.','The still river stayed at the same level all day.','Surging describes rising or rushing movement, not remaining motionless.'),[Q("surging.q1","surging.s1","meaning","What does surging river water do?","Rises and rushes with force.","Remains perfectly still.","Turns into dry soil.","Surging describes rising and forceful movement."),Q("surging.q2","surging.s1","context","Which number is surging?","Requests jump rapidly from 20 to 200 in an hour.","Requests remain at 20 all week.","Requests disappear permanently.","A rapidly increasing count is surging."),Q("surging.q3","surging.s1","word-choice","Choose a natural phrase.","surging crowds filled the station","surgingly crowd station","crowds surgingly at yesterday","Surging modifies crowds to describe their forceful movement."),Q("surging.q4","surging.s1","distinction","Why did the crew watch surging water carefully?","It was rising or rushing and could overflow the bank.","It was motionless and guaranteed safe.","It was a late meal after work.","The participle warns of rising, forceful water.")]);
P('surmise','From Anglo-French surmise, from surmettre “put over, suggest.” As a noun it is an idea based on incomplete evidence; as a verb it means guess without full proof.','Anglo-French surmise, from surmettre “put over, suggest”','From the muddy footprints, we surmised that someone had entered through the garden.','從泥濘的腳印，我們推測有人從花園進入。','investigation','Noun sense 1: an idea formed from incomplete evidence; verb sense 2: guess that something is true without full proof.','The context uses the verb: the footprints provide clues, but not complete proof.',M('We surmised the visitor’s identity from muddy prints even though the prints contained no information at all.','We guessed the visitor’s identity from muddy prints, while recognizing that the evidence was incomplete.','Surmise is an inference from some evidence; no information at all cannot support the guess.'),[Q("surmise.q1","surmise.s1","meaning","What is a surmise?","An idea formed from incomplete evidence.","A fact directly proven beyond doubt.","A written title beneath a heading.","As a noun, surmise is an idea formed from incomplete evidence."),Q("surmise.q2","surmise.s2","context","What did the investigators do when they surmised the visitor came through the garden?","They guessed from clues without having full proof.","They proved the route with an unbroken video record.","They charged the visitor an extra fee.","The verb means guess that something is true without full proof."),Q("surmise.q3","surmise.s1","distinction","Why label an early explanation a surmise?","It is a tentative idea based on limited clues.","It is a completed surgery.","It is a claim established by full proof.","The noun marks an assumption made from incomplete evidence."),Q("surmise.q4","surmise.s2","grammar","Which sentence uses “surmise” as a verb?","I surmise that the lights failed during the storm.","My surmise was based on two clues.","The surmise appeared in a subtitle.","In the first sentence, surmise is the action of making a guess.")]);
P('surmount','From Old French surmonter, from sur- “over” + monter “climb.” It means overcome a difficulty or be positioned on top of something.','Old French surmonter: sur- “over” + monter “climb”','With careful planning, the team surmounted the logistical problems and completed the rescue.','透過仔細規劃，團隊克服了後勤問題並完成救援。','problem solving','Verb sense 1: succeed in dealing with a difficulty or barrier; sense 2: stand or be built on top of something.','The context uses the overcoming sense; a tower or ornament may also surmount a structure physically.',M('The team surmounted the obstacle by giving up before reaching it.','The team overcame the obstacle and continued to the destination.','Surmount means succeed in dealing with a problem or barrier, not abandon the effort.'),[Q("surmount.q1","surmount.s1","meaning","What does it mean to surmount a problem?","Successfully overcome or deal with it.","Make it more difficult on purpose.","Place it in a supermarket.","The first sense is to succeed in dealing with a problem or barrier."),Q("surmount.q2","surmount.s2","context","A statue surmounts the entrance arch. Where is it?","On top of the arch.","Buried below the foundation.","Inside a moving subway train.","The second sense means stand or be built on the top of something."),Q("surmount.q3","surmount.s1","distinction","Which action surmounts a language barrier?","Learning enough of the language to communicate successfully.","Ignoring every attempt to communicate.","Adding a fee to a ticket.","Overcoming the barrier fits the first sense."),Q("surmount.q4","surmount.s2","word-choice","Which sentence uses the physical-position sense?","A stone crest surmounts the doorway.","She surmounted her fear before the speech.","The barrier was hard to surmount.","The crest stands on top of the doorway; the other examples use overcome.")]);
P('surname','From Anglo-French surname, from Old French surnom, formed from sur- “above, additional” + nom “name.”','Anglo-French surname, from Old French surnom “additional name”','The twins share the same surname even though their given names are different.','這對雙胞胎的姓氏相同，儘管他們的名字不同。','family','Noun: the family name shared with other members of a family.','The context contrasts surname with given name.',M('Her surname was the name her parents chose only for her, while her family used another name.','Her given name was chosen for her, while her surname was shared with her family.','A surname is the family name shared with relatives; an individually chosen first name is a given name.'),[Q("surname.q1","surname.s1","meaning","Which part of a person’s name is the surname?","The family name shared with relatives.","The first name used only for one person.","A title printed beneath a book title.","The source defines surname as the name shared with other family members."),Q("surname.q2","surname.s1","context","If two cousins share “Nguyen” as a surname, what do they share?","A family name.","A first name that must be identical.","A home address.","Surname refers to the shared family name, not necessarily the given name."),Q("surname.q3","surname.s1","distinction","Which is most likely a surname in “Maya Chen”?","Chen","Maya","Both are titles of books.","In this name, Chen is the family name and Maya is the given name."),Q("surname.q4","surname.s1","word-choice","Which phrase is natural?","write your surname on the form","write your surnamely on the form","surname the form before reading","Surname is a countable noun for a family name.")]);
P('surpass','From Old French surpasser, from sur- “over, beyond” + passer “pass.”','Old French surpasser: sur- “beyond” + passer “pass”','The young pianist began to surpass her teacher in speed and precision.','這位年輕鋼琴家的速度與精準度開始超越老師。','music','Verb sense 1: be better than someone; sense 2: be greater than a number or limit.','The context compares ability; the word also describes an amount exceeding a threshold.',M('The new model surpassed the old one by performing worse in every test.','The new model fell short of the old one by performing worse in every test.','Surpass means be better or greater; performing worse does not surpass the older model.'),[Q("surpass.q1","surpass.s1","meaning","What does it mean to surpass a rival in skill?","Perform better than the rival.","Perform worse than the rival.","Stand physically above the rival.","The first sense is to be better than someone at something."),Q("surpass.q2","surpass.s2","context","A storm’s cost surpassed $2 million. What happened?","The cost became greater than $2 million.","The cost stayed below $2 million.","The storm was replaced by a survey.","The amount sense means greater than a number or limit."),Q("surpass.q3","surpass.s1","collocation","Which phrase is standard?","surpass expectations","surpass to expectations","surpass expectationsly","Surpass takes its object directly without a preposition."),Q("surpass.q4","surpass.s2","distinction","A crowd limit is 500; attendance reaches 620. Did attendance surpass the limit?","Yes; 620 is greater than 500.","No; 620 is less than 500.","No; surpass means equal exactly.","Surpass can mean go beyond a number or limit.")]);
P('surpassingly','Formed from surpass + -ing + -ly; surpass comes from Old French surpasser “go beyond.”','surpass + -ing + -ly; surpass from Old French surpasser “go beyond”','The renovated hall is surpassingly beautiful, with its original stone arches still visible.','翻新後的大廳美得非凡，原有的石拱仍清晰可見。','architecture','Adverb: surpassingly means in a way that goes beyond the ordinary.','It modifies beautiful to indicate an exceptional degree.',M('The ordinary plain hall was surpassingly unremarkable and no different from any other room.','The hall was ordinary and unremarkable, unlike a surpassingly beautiful space.','Surpassingly indicates going beyond the ordinary, not being ordinary and unremarkable.'),[Q("surpassingly.q1","surpassingly.s1","meaning","What does “surpassingly beautiful” mean?","Beautiful to an exceptional degree.","Ordinary and easy to overlook.","Physically higher than the ceiling.","Surpassingly means in a way that goes beyond the ordinary."),Q("surpassingly.q2","surpassingly.s1","context","Which sentence uses “surpassingly” naturally?","The valley was surpassingly quiet at dawn.","The valley surpassingly the road yesterday.","They bought a surpassingly at the shop.","The adverb modifies quiet to mean exceptionally quiet."),Q("surpassingly.q3","surpassingly.s1","distinction","Is a merely average result surpassingly strong?","No; surpassingly signals an unusually high degree.","Yes; it means exactly average.","No; it means below ground.","The adverb marks something beyond the ordinary."),Q("surpassingly.q4","surpassingly.s1","word-choice","Which phrase is closest in meaning?","surpassingly rare","slightly common","completely ordinary","Surpassingly describes an extreme or exceptional degree.")]);
P('surplus','From Old French surplus “overplus, excess,” from sur- “over” + plus “more.” It can be excess quantity, financial excess, or an adjective meaning extra.','Old French surplus “overplus,” from sur- “over” + plus “more”','The farm sold its surplus grain after setting aside enough for the winter.','農場留足冬季所需後，出售了剩餘穀物。','agriculture','Noun sense 1: amount left after needs are met; sense 2: money left when income exceeds spending; adjective sense 3: more than needed.','The context uses excess physical stock; the word also names a budget surplus and modifies an extra item.',M('The farm’s surplus grain was the exact amount needed, with none left over.','The farm had no surplus grain because it used exactly what it needed.','A surplus is what remains after needs are met; an exact amount with nothing left is not surplus.'),[Q("surplus.q1","surplus.s1","meaning","What is surplus grain?","Grain left after the amount needed has been set aside.","The only grain available when none is left over.","A crop that has not been planted.","The first sense is an amount left after what is needed has been used."),Q("surplus.q2","surplus.s2","context","A city’s revenue exceeds spending by $3 million. What may it have?","A budget surplus.","A budget deficit.","A medical surgery.","The financial sense is money left when income is greater than spending."),Q("surplus.q3","surplus.s3","grammar","Which sentence uses “surplus” as an adjective?","The warehouse sold surplus equipment.","A surplus remained in the account.","They surveyed the warehouse.","In the first sentence surplus modifies equipment to mean more than needed."),Q("surplus.q4","surplus.s1","distinction","If a store has a surplus of chairs, what is true?","It has more chairs than it needs or plans to use.","It has no chairs at all.","Every chair is already broken.","Surplus is an amount remaining beyond what is required.")]);
P('surprise','From Old French surprise, past participle of surprendre “overcome, take unawares,” from sur- “over” + prendre “take.” It can be a feeling, event, or verb.','Old French surprise, from surprendre “take unawares”','The unexpected snowfall came as a surprise to the drivers.','這場意外降雪讓駕駛人感到驚訝。','weather','Noun sense 1: feeling caused by something unexpected; sense 2: an unexpected event; verb sense 3: make someone feel surprise or catch unexpectedly.','The context uses the emotional reaction; surprise can also name the event or describe causing the reaction.',M('The forecasted snowfall was a surprise because everyone had expected it for weeks.','The unexpected snowfall was a surprise because no one had predicted it.','A surprise is unexpected; an event anticipated for weeks is not surprising.'),[Q("surprise.q1","surprise.s1","meaning","What feeling is surprise?","The reaction to something unexpected.","A feeling of complete routine.","A person who measures land.","The first sense is the feeling when something unexpected happens."),Q("surprise.q2","surprise.s2","context","A party planned in secret for a guest is what?","A surprise event.","A survey of the guests.","A known weekly appointment.","The second sense is an unexpected event."),Q("surprise.q3","surprise.s3","grammar","Which sentence uses “surprise” as a verb?","The sudden visit surprised her.","The visit was a surprise.","Her surprise lasted a minute.","Surprised is the verb form meaning made her feel surprise."),Q("surprise.q4","surprise.s1","distinction","Why did the early snowfall cause surprise?","It happened when drivers did not expect it.","It followed a precise forecast everyone had read.","It was a routine part of summer weather.","Unexpectedness is central to the feeling sense.")]);
P('surrealism','From French surréalisme, formed from sur- “beyond” + réalisme “realism”; the movement combines dreamlike images with ordinary life.','French surréalisme: sur- “beyond” + réalisme “realism”','The painting’s melting clocks and familiar landscape show the dreamlike juxtapositions of surrealism.','畫中的融化時鐘與熟悉景色展現了超現實主義的夢境式並置。','art','Noun: surrealism is an art and literature movement joining dream images with ordinary life.','The context links an ordinary setting with impossible dreamlike objects.',M('The realist landscape, copied exactly from a photograph with no dream imagery, was a clear example of surrealism.','The melting clocks placed in a familiar landscape were a clear example of surrealism.','Surrealism joins dreamlike imagery with ordinary life; a strictly realistic copy lacks that juxtaposition.'),[Q("surrealism.q1","surrealism.s1","meaning","What does surrealism combine?","Dreamlike images with ordinary life.","Only exact technical diagrams.","A survey with a medical operation.","The movement joins dream imagery and ordinary life."),Q("surrealism.q2","surrealism.s1","context","Which painting best fits surrealism?","A familiar bedroom with a staircase floating through the sky.","A precise photograph of a plain wall.","A map showing measured property lines only.","The impossible dreamlike staircase is set in ordinary surroundings."),Q("surrealism.q3","surrealism.s1","distinction","Why can a melting clock in a realistic room feel surrealist?","It places dreamlike imagery beside an ordinary setting.","It is a standard tool for measuring time.","It depicts a normal clock repair manual.","Surrealism creates unexpected dream-and-reality combinations."),Q("surrealism.q4","surrealism.s1","word-choice","Which sentence uses “surrealism” correctly?","The gallery devoted a room to surrealism and its dreamlike images.","The surrealism measured the garden boundary.","She surrealismed the clock.","Surrealism is the name of an art and literature movement.")]);
P('surrender','From Anglo-French surrendre, from Old French rendre “give back, yield,” with sur- “over.” It means stop fighting, give something up, or the act of yielding.','Anglo-French surrendre, from Old French rendre “give back, yield”','After hours of negotiation, the besieged commander agreed to surrender the fort.','經過數小時談判，被圍困的指揮官同意交出要塞。','history','Verb sense 1: stop fighting and admit defeat; sense 2: give something up because required; noun sense 3: the act of admitting defeat or giving something up.','The context uses the cease-fighting sense; surrender can also mean hand over property or name the act itself.',M('The commander surrendered the fort but kept control of it and refused to hand it over.','The commander surrendered the fort by giving up control and handing it over.','Surrender means stop fighting or give something up; keeping control is not surrender.'),[Q("surrender.q1","surrender.s1","meaning","What does an army do when it surrenders?","Stops fighting and admits defeat.","Wins the battle and captures the opposing army.","Surveys the land for a new road.","The first sense is to stop fighting and admit that one has lost."),Q("surrender.q2","surrender.s2","context","A driver surrenders a license after a court order. What happens?","The driver gives the license to the authority because required.","The driver takes the license back without permission.","The driver wins a battle.","The second sense is to give something to another person because one must."),Q("surrender.q3","surrender.s3","meaning","What does “the surrender was signed at noon” name?","The act or agreement of admitting defeat or giving something up.","A person who measures land.","A feeling of surprise.","The noun sense names the act of yielding or giving something up."),Q("surrender.q4","surrender.s1","distinction","Which event is a surrender in battle?","The defenders stop fighting and accept defeat.","The defenders continue fighting and capture the city.","The defenders replace an old rule with a new one.","Surrender means cease fighting and admit defeat.")]);
P('surround','From a historical form related to Old French suronder “overflow” and influenced by round; modern senses are to go all around or be closely connected with a situation.','historically related to Old French suronder “overflow”; later influenced by round','Tall trees surround the cabin on every side.','高大的樹木從四面環繞著小木屋。','nature','Verb sense 1: be or go all around a person or place; sense 2: be closely connected with a situation.','The context uses the spatial sense; facts, circumstances, or questions can also surround a situation.',M('A single tree surrounded the cabin but stood on only one side of it.','Trees surrounded the cabin on every side.','To surround a place is to be or go all around it, not stand on just one side.'),[Q("surround.q1","surround.s1","meaning","What does it mean for trees to surround a cabin?","They stand all around it.","They grow only in one distant forest.","They hang from its roof.","The first sense means be or go all around a person or place."),Q("surround.q2","surround.s2","context","What does “questions surround the decision” mean?","Questions are closely connected with or cast doubt on it.","Questions are physically planted around a room.","The decision has been suspended in air.","The second sense relates surrounding to the circumstances or issues around a situation."),Q("surround.q3","surround.s1","grammar","Choose the correct sentence.","A wall surrounds the garden.","A wall surround the garden yesterday.","A wall is surround the garden.","The third-person singular present form is surrounds."),Q("surround.q4","surround.s1","distinction","Which scene shows a place surrounded?","A ring of hills lies on every side of the village.","A hill stands far beyond the village to the east.","A room has one tree painted on its wall.","A ring around every side illustrates the spatial sense.")]);
P('surrounding','Present participle/adjective of surround, ultimately related to Old French suronder “overflow.”','surround + -ing; related to Old French suronder','The surrounding hills shelter the farm from strong coastal winds.','周圍的山丘替農場擋住強勁海風。','geography','Adjective: surrounding places or objects are located on all sides of something.','The adjective modifies hills and locates them around the farm.',M('The surrounding hills stood only on the far side of the continent, nowhere near the farm.','Distant hills stood across the continent, not in the farm’s surrounding area.','Surrounding means located on all sides or nearby, not far away across a continent.'),[Q("surrounding.q1","surrounding.s1","meaning","What are a building’s surrounding streets?","The streets located around it.","Streets on the opposite side of the country.","Streets inside its roof.","Surrounding means located on all sides of something."),Q("surrounding.q2","surrounding.s1","context","Which phrase uses the adjective naturally?","the surrounding countryside","the surrounding yesterday","to surrounding the room","Surrounding modifies a noun to describe nearby or encircling places."),Q("surrounding.q3","surrounding.s1","distinction","If surrounding hills shelter a farm, where are the hills?","Around the farm on several sides.","Only inside the farmhouse kitchen.","On a different continent.","The adjective indicates location around the farm."),Q("surrounding.q4","surrounding.s1","word-choice","Which sentence is correct?","We explored the surrounding villages by bicycle.","We surrounding explored villages bicycle.","The villages surroundingly were yesterday.","Surrounding is an adjective that modifies villages.")]);
P('surroundings','Formed from surrounding + -s; surrounding is from surround, a verb meaning go all around.','surrounding + -s; surround means go all around','The rescued hikers rested in quiet surroundings near the ranger station.','獲救的健行者在護林站附近安靜的環境中休息。','outdoors','Noun sense 1: natural objects, places, and conditions around someone; sense 2: the place and conditions where someone lives or works.','The context uses a setting around people; surroundings can include the wider living or working environment.',M('She felt at home in her new surroundings, which consisted of no place or conditions around her.','She felt at home in her new surroundings, with familiar people and places around her.','Surroundings are the places and conditions around a person; the first sentence contradicts the word.'),[Q("surroundings.q1","surroundings.s1","meaning","What are someone’s surroundings?","The nearby places, objects, and conditions around them.","Only the person’s surname.","A single word in a book title.","The first sense is the natural objects, places, and conditions around a person."),Q("surroundings.q2","surroundings.s2","context","A worker moves to a new office and adjusts to the surroundings. What is meant?","The workplace and conditions affecting daily work.","Only the worker’s childhood landscape.","A medical operation.","The second sense is the place where someone lives or works and its conditions."),Q("surroundings.q3","surroundings.s1","distinction","Which details belong to a campsite’s surroundings?","Nearby trees, rocks, paths, and weather conditions.","A distant person’s middle name only.","The campsite’s future surveyor.","Surroundings include places and conditions around a location."),Q("surroundings.q4","surroundings.s2","word-choice","Which sentence uses “surroundings” naturally?","The new employee learned the office surroundings during her first week.","The employee surroundings the desk yesterday.","They bought a surroundings at lunch.","The plural noun names the environment where someone lives or works.")]);
P("surveillance", "From French surveiller, “to watch over,” from sur- “over” and veiller “to watch”; ultimately from Latin vigilare, “to stay awake.”", [C("surveillance.s1", "public safety", "The station installed cameras for the surveillance of its entrances.", "車站安裝攝影機監視各個入口。", "surveillance of + a place or people", "Noun for close watching of people or places, often to prevent crime.", "This is the close-monitoring sense; surveillance can also mean continuous checking of a disease or system.")], [M("The surveillance cameras ensured that nobody watched the station entrances.", "The surveillance cameras enabled staff to watch the station entrances.", "Surveillance means close watching; saying nobody watched reverses the meaning.", "meaning")], [Q("surveillance.q1", "surveillance.s1", "meaning", "What does camera surveillance at a station involve?", "Closely watching the station and its entrances.", "Leaving the entrances unobserved.", "Measuring the height of the platform.", "Surveillance is close watching of people or places."), Q("surveillance.q2", "surveillance.s2", "context", "What might disease surveillance track?", "Cases of an illness over time.", "The color of a station sign once.", "A person’s family name.", "The second sense is continuous checking of a disease or system."), Q("surveillance.q3", "surveillance.s1", "collocation", "Which phrase is natural?", "video surveillance of the car park", "surveillance to the breakfast", "a surveillance of three apples only", "Surveillance commonly describes close monitoring of a place."), Q("surveillance.q4", "surveillance.s1", "distinction", "How does surveillance differ from a survey?", "Surveillance is ongoing close watching; a survey gathers answers or measures land.", "Surveillance is always a one-time questionnaire.", "The words both mean a person who measures land.", "The first sense is close watching, while survey has separate questionnaire and land-measurement senses.")]);
P("survey", "From Old French surveoir, “to look over,” from sur- “over” and veoir “see,” ultimately from Latin videre, “to see.”", [C("survey.s1", "public opinion", "The researchers conducted a survey of 600 residents about bus service.", "研究人員針對六百位居民進行公車服務民意調查。", "conduct a survey of + a group", "Noun: a set of questions asked of many people to gather facts or opinions.", "The context describes collecting residents’ opinions; survey can also mean measuring land or examining something carefully.") , C("survey.s3", "inspection", "Before buying the house, we surveyed every room for signs of water damage.", "買房前，我們仔細檢查每個房間是否有漏水跡象。", "survey + an area or subject", "Verb: to look carefully over something, or to study and describe it.", "Here survey means examine carefully, rather than ask people questions.")], [M("The survey of residents asked no questions and gathered no facts or opinions.", "The survey of residents asked questions to gather their views on bus service.", "A survey in this sense is a set of questions used to gather facts or opinions.", "meaning")], [Q("survey.q1", "survey.s1", "meaning", "What is a public-opinion survey designed to collect?", "Facts or opinions from answers given by many people.", "The exact height of one mountain only.", "A list of people suspected of a crime.", "The first sense is a set of questions used to gather facts or opinions."), Q("survey.q2", "survey.s2", "distinction", "What does a land survey record?", "The shape and size of a piece of land.", "How residents feel about a bus route.", "The number of cameras watching a shop.", "The second sense is an examination of land to record its shape and size."), Q("survey.q3", "survey.s3", "context", "In “survey the evidence,” what does survey mean?", "Look carefully over and study the evidence.", "Ask the evidence to complete a questionnaire.", "Hang the evidence from a point.", "The verb sense means examine or study something carefully."), Q("survey.q4", "survey.s1", "word-choice", "Which phrase uses the questionnaire sense?", "complete a survey about library hours", "survey the coastline with measuring equipment", "survey the room before describing it", "A survey about library hours gathers people’s answers.")]);
P("surveyor", "From survey + -or, with survey from Old French surveoir, “to look over.”", [C("surveyor.s1", "land measurement", "A surveyor marked the property boundaries before construction began.", "施工開始前，測量員標出了土地界線。", "a surveyor marks or measures land", "Noun: a person whose job is to measure land and mark boundaries.", "The sentence uses the land-measurement occupation; a surveyor may also inspect a building, ship, or goods.") , C("surveyor.s2", "inspection", "The building surveyor inspected the roof and foundation for structural damage.", "建築檢驗員檢查屋頂與地基是否有結構損壞。", "building surveyor inspects a property", "Noun: a person who examines a building, ship, or goods for condition.", "This is the inspection occupation, distinct from measuring land boundaries.")], [M("The surveyor marked the boundary by asking residents which bus route they preferred.", "The surveyor measured the property and marked its boundary.", "A surveyor in the first sense measures land; collecting opinions is conducting a survey.", "word-choice")], [Q("surveyor.q1", "surveyor.s1", "meaning", "What does a land surveyor do?", "Measures land and marks its boundaries.", "Watches people with security cameras.", "Collects rainwater from a roof.", "The first sense is a person whose job is measuring land and marking boundaries."), Q("surveyor.q2", "surveyor.s2", "context", "Why might a buyer hire a building surveyor?", "To examine the building’s condition.", "To ask every neighbor to vote on a bus route.", "To mark a national border from orbit.", "The second sense is a person who examines buildings or other property."), Q("surveyor.q3", "surveyor.s1", "distinction", "Which job is specifically the land-measurement sense?", "A worker measures a parcel and records its boundary lines.", "A worker checks a ship for damage before sale.", "A worker asks residents about a new park.", "The first sense concerns measuring land; the second concerns inspecting condition."), Q("surveyor.q4", "surveyor.s2", "collocation", "Which phrase is natural?", "a surveyor inspected the warehouse roof", "a surveyor questioned the whole city about lunch", "a surveyor watched the doorway on camera", "Inspecting a building’s condition matches the second surveyor sense.")]);
P("survivability", "Formed from survive + -ability; survive came through Old French survivre from Latin super- “over, beyond” + vivere “to live.”", [C("survivability.s1", "engineering", "Engineers tested the capsule’s survivability after exposure to extreme heat.", "工程師測試太空艙暴露於極端高溫後的存活能力。", "survivability of + a person, system, or vehicle", "Noun: the capacity of a person, species, system, or vehicle to survive a threat.", "The word names a capacity to survive a hazard, not survival after the hazard has already passed.")], [M("The capsule’s survivability was its certainty of failing immediately in every test.", "The capsule’s survivability was its capacity to remain intact through the tests.", "Survivability is a capacity to survive a threat, not a guarantee of failure.", "meaning")], [Q("survivability.q1", "survivability.s1", "meaning", "What does a vehicle’s survivability describe?", "Its capacity to survive a threat or damaging event.", "The number of people who have already escaped it.", "Its fuel cost on an ordinary day.", "Survivability is the capacity of a person, system, or vehicle to survive a threat."), Q("survivability.q2", "survivability.s1", "context", "Why test a capsule’s survivability in extreme heat?", "To learn whether it can withstand that hazard.", "To count how many cameras are inside it.", "To ask passengers to complete a questionnaire.", "The test evaluates the capsule’s capacity to survive a threat."), Q("survivability.q3", "survivability.s1", "distinction", "How does survivability differ from survival?", "Survivability is capacity to survive; survival is the act or fact of continuing to live or exist.", "Survivability means a person who remains alive after an accident.", "Survival means a vehicle’s ability to resist a future threat only.", "The suffix -ability makes survivability a capacity, while survival names the act or fact."), Q("survivability.q4", "survivability.s1", "word-choice", "Which phrase fits the meaning of survivability?", "the survivability of a species during drought", "the survivability of the report’s punctuation", "the survivability of a person’s surname", "A species can have a capacity to survive a threat such as drought.")]);
P("survival", "From survive + -al; survive came through Old French survivre from Latin super- “over, beyond” + vivere “to live.”", [C("survival.s1", "disaster response", "After the flood, the family’s survival depended on clean water and a safe shelter.", "洪水過後，這家人的生存仰賴乾淨的水與安全的避難處。", "survival depends on + a resource or condition", "Noun: the act or fact of continuing to live or exist after danger or difficulty.", "The context describes remaining alive after a dangerous event; survival can also mean the resources needed to stay alive or a remnant from the past.") , C("survival.s3", "history", "The stone tool is a survival from an earlier period of settlement.", "這件石器是早期聚落時期留存下來的遺物。", "a survival from + an earlier period", "Noun: something that has continued to exist from an earlier time.", "This countable use refers to a remnant that has lasted from the past.")], [M("Their survival after the flood meant that none of them remained alive or safe.", "Their survival after the flood meant that they remained alive and found safe shelter.", "Survival after danger means continuing to live or exist, not that everyone died.", "meaning")], [Q("survival.q1", "survival.s1", "meaning", "What does survival after a flood mean?", "Continuing to live or exist after the dangerous event.", "Being the person who measures land boundaries.", "An extra fee added to a hotel bill.", "The first sense is continuing to live or exist after a dangerous event."), Q("survival.q2", "survival.s2", "context", "In a remote winter, what might “the basics for survival” include?", "Food, water, and money needed to stay alive.", "A collection of old stone tools only.", "Questions asked in a public-opinion poll.", "The second sense is the food, water, and money needed to stay alive."), Q("survival.q3", "survival.s3", "distinction", "A custom kept for centuries is described as a survival from the past. What does survival mean here?", "Something that has continued to exist from an earlier time.", "A person rescued from a recent accident.", "A capacity to withstand heat in the future.", "The third sense is a thing that remains from an earlier time."), Q("survival.q4", "survival.s1", "collocation", "Which phrase is natural after a shipwreck?", "the crew’s survival at sea", "the crew’s survival to the harbor with a map", "the crew’s survival of a camera watching them", "Survival at sea describes remaining alive after a dangerous event.")]);
P("survive", "From Old French survivre, from Latin super- “over, beyond” + vivere “to live.”", [C("survive.s1", "emergency", "All passengers survived the crash and were treated for minor injuries.", "所有乘客在事故中倖存，並接受了輕傷治療。", "survive + an accident, illness, or disaster", "Verb: to continue to live after an accident, illness, or disaster.", "The sentence uses the remain-alive sense; survive can also mean continue to exist or live longer than someone else.") , C("survive.s3", "family history", "She survived her older brother by twelve years.", "她比哥哥多活了十二年。", "survive + a person", "Verb: to live longer than another person.", "Here survive compares lifespans, rather than describing recovery from an event.")], [M("Every passenger survived the crash, so every one of them died at the scene.", "Every passenger survived the crash, so every one of them remained alive.", "To survive a crash means to continue living after it; it cannot mean dying at the scene.", "meaning")], [Q("survive.q1", "survive.s1", "meaning", "If a person survives an accident, what happened?", "The person continued to live after it.", "The person caused it to happen again.", "The person measured the accident site for a property map.", "The first sense is continuing to live after an accident or disaster."), Q("survive.q2", "survive.s2", "context", "If a tradition survives for centuries, what does that mean?", "It continues to exist over that period.", "It lives longer than one named person only.", "It is closely watched by cameras.", "The second sense is to continue to exist after time or difficulty."), Q("survive.q3", "survive.s3", "distinction", "If Maya survived Leo by five years, what is meant?", "Maya lived five years longer than Leo.", "Maya watched Leo closely for five years.", "Maya collected five years of survey answers from Leo.", "The third sense means to live longer than another person."), Q("survive.q4", "survive.s1", "collocation", "Which sentence uses survive in the accident sense?", "The hikers survived the storm by taking shelter.", "The hikers survived their friend by bringing him a map.", "The hikers survived a questionnaire about the storm.", "Survive a storm means continue living after the dangerous event.")]);
P("survivor", "From survive + -or, with survive from Old French survivre and Latin super- “beyond” + vivere “to live.”", [C("survivor.s1", "rescue", "A survivor of the earthquake described how neighbors helped one another.", "一名地震倖存者描述鄰居如何互相幫助。", "a survivor of + a disaster", "Noun: a person who remains alive after a dangerous event.", "The noun refers to a person who remains alive after the earthquake, not someone monitoring the rescue.")], [M("The survivor of the shipwreck was the person who drowned and did not remain alive.", "The survivor of the shipwreck was the person who remained alive after it.", "A survivor is someone who remains alive after a dangerous event.", "meaning")], [Q("survivor.q1", "survivor.s1", "meaning", "Who is a survivor of an earthquake?", "A person who remains alive after the earthquake.", "A person who measures the property boundary.", "A person who adds an extra charge.", "The sense is a person who remains alive after a dangerous event."), Q("survivor.q2", "survivor.s1", "context", "Why might a survivor speak at a memorial?", "To describe the experience of living through the disaster.", "To explain how to inspect a ship’s hull for damage.", "To ask visitors to fill out a bus survey.", "A survivor has remained alive after the event and can describe it."), Q("survivor.q3", "survivor.s1", "distinction", "How does survivor differ from survival?", "A survivor is a person; survival is the act or fact of continuing to live.", "A survivor is a future capacity; survival is a camera system.", "Both words mean the same thing as surveyor.", "The suffix -or refers to a person, while survival names an act or state."), Q("survivor.q4", "survivor.s1", "collocation", "Which phrase is natural?", "a survivor of the plane crash", "a survivor the plane crash by camera", "a survivor of measuring the boundary", "A survivor of a crash is a person who remained alive after it.")]);
P("susceptible", "From Latin susceptibilis, “capable of receiving,” from suscipere “to take up, receive.”", [C("susceptible.s1", "health", "Young seedlings are susceptible to frost damage.", "幼苗容易受到霜害。", "susceptible to + a harm or influence", "Adjective: likely to be harmed or influenced by something.", "The context concerns likely physical harm; susceptible can also describe emotional responsiveness or openness to an idea.") , C("susceptible.s2", "persuasion", "He is susceptible to a well-supported argument, even when it challenges his first opinion.", "即使有力的論據挑戰他原先的看法，他也願意接受。", "susceptible to + an idea or appeal", "Adjective: easily moved emotionally, or willing to accept an idea.", "This context uses openness to an idea, rather than vulnerability to physical harm.")], [M("The seedlings were susceptible to frost, so cold weather could not harm them.", "The seedlings were susceptible to frost, so cold weather could harm them.", "Susceptible to a harm means likely to be affected by it.", "meaning")], [Q("susceptible.q1", "susceptible.s1", "meaning", "If a crop is susceptible to disease, what is true?", "It is likely to be harmed by the disease.", "It is guaranteed to cure the disease.", "It is a person who inspects the crop for sale.", "The first sense means likely to be harmed or influenced."), Q("susceptible.q2", "susceptible.s2", "context", "A listener is susceptible to a persuasive argument. What does that suggest?", "The listener may be willing to accept the idea.", "The listener is physically suspended from a point.", "The listener is asking a land-survey question.", "The second sense includes willingness to accept an idea."), Q("susceptible.q3", "susceptible.s1", "collocation", "Which phrase is natural?", "susceptible to infection", "susceptible from the calendar", "susceptible at a boundary line", "Susceptible commonly takes to before a possible harm or influence."), Q("susceptible.q4", "susceptible.s2", "distinction", "Which example uses the emotional or idea-acceptance sense?", "She is susceptible to appeals for help.", "The metal is susceptible to rust.", "The seeds are susceptible to frost.", "The first example describes being emotionally moved by an appeal.")]);
P("suspect", "From Latin suspectus, past participle of suspicere, “to look up at, mistrust,” from sub- “from below” + specere “to look.”", [C("suspect.s1", "investigation", "Police suspect that the missing files were copied before the office closed.", "警方懷疑遺失的檔案在辦公室關門前遭到複製。", "suspect that + a clause", "Verb: to think that something is probably true, without proof.", "The verb expresses an unproved belief; suspect is also a noun for a person thought guilty and an adjective meaning possibly untrustworthy.") , C("suspect.s2", "law", "The suspect was questioned but released when no evidence connected him to the theft.", "嫌疑犯接受詢問後獲釋，因為沒有證據將他與竊案連結。", "a suspect in + a crime", "Noun: a person who is thought to be guilty of a crime.", "This noun labels a person under suspicion; it does not state that guilt has been proven.") , C("suspect.s3", "quality control", "The inspector rejected a suspect batch of medicine because its label might be false.", "檢驗員拒收一批標示可能不實的可疑藥品。", "suspect + a thing or claim", "Adjective: possibly false or dangerous, and not to be trusted.", "The adjective describes something questionable or unsafe, rather than a person accused of a crime.")], [M("Police suspect that the files were copied, which means they proved it beyond any doubt.", "Police suspect that the files were copied, but they do not yet have proof.", "Suspect as a verb means think something is probably true without proof.", "meaning")], [Q("suspect.q1", "suspect.s1", "meaning", "If investigators suspect that a file was copied, what do they believe?", "They think it probably happened, but do not have proof.", "They have already proved every detail beyond doubt.", "They are measuring the file’s physical dimensions.", "The verb sense is an unproved belief that something is probably true."), Q("suspect.q2", "suspect.s2", "context", "Who is a suspect in a theft investigation?", "A person thought to be guilty of the crime.", "A person who takes a public-opinion survey.", "A person who watches a disease over time.", "The noun sense is a person thought to be guilty of a crime."), Q("suspect.q3", "suspect.s3", "distinction", "What does a suspect document mean?", "A document that may be false or untrustworthy.", "A document already proved correct and authentic.", "A document that measures the land around a house.", "The adjective describes something possibly false or not to be trusted."), Q("suspect.q4", "suspect.s1", "grammar", "Which sentence uses suspect as a verb?", "I suspect the road is closed because no cars are passing.", "The suspect waited outside the courthouse.", "The inspector rejected a suspect label.", "In the first sentence suspect is followed by a clause and means think probably true without proof.")]);
P("suspend", "From Latin suspendere, “to hang up,” from sub- “under” + pendere “to hang.”", [C("suspend.s1", "household", "Suspend the lantern from a hook above the table.", "把燈籠掛在桌子上方的掛鉤上。", "suspend + an object + from + a point", "Verb: to hang something from a point so that it does not touch the ground.", "The instruction uses the physical hanging sense; suspend can also pause an activity or impose a temporary penalty.") , C("suspend.s2", "business", "The company suspended deliveries for two days while the bridge was repaired.", "橋梁維修期間，公司暫停配送兩天。", "suspend + an activity + for + a period", "Verb: to stop something for a period of time.", "The deliveries are paused temporarily, not ended permanently.") , C("suspend.s3", "school", "The school suspended the student for three days after repeated violations of the safety rules.", "學生多次違反安全規定後，學校讓他停學三天。", "suspend + a person + from school or work", "Verb: to stop someone from working or studying for a time as a punishment.", "This is a temporary disciplinary penalty, distinct from simply pausing an activity.")], [M("The school suspended the student for three days, so he attended every class as usual during those days.", "The school suspended the student for three days, so he was temporarily barred from classes.", "To suspend someone from school as punishment is to stop them studying there for a period.", "meaning")], [Q("suspend.q1", "suspend.s1", "meaning", "If you suspend a lantern from a hook, what do you do?", "Hang it from the hook so it does not touch the ground.", "Stop the lantern from being used for two days as punishment.", "Measure the hook and ask neighbors for opinions.", "The first sense means hang something from a point."), Q("suspend.q2", "suspend.s2", "context", "If deliveries are suspended during bridge repairs, what happens?", "They are temporarily stopped.", "They are hung from the bridge.", "They are permanently doubled.", "The second sense is to stop an activity for a period of time."), Q("suspend.q3", "suspend.s3", "distinction", "A player is suspended for breaking a rule. What does that mean?", "The player is temporarily barred from playing as a penalty.", "The player is physically hung from the scoreboard.", "The game has continued without any pause or penalty.", "The third sense is temporarily stopping someone from work or study as punishment."), Q("suspend.q4", "suspend.s2", "collocation", "Which phrase uses the temporary-stop sense?", "suspend operations for a week", "suspend a lamp from the ceiling", "suspend a student from school", "Suspending operations for a week means pausing the activity for a period.")]);
})();
